window.QUIZ_ZK_DATA["java13215"]=[{"id":"java13215-pl-P4085731","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java语言是由哪家公司开发的，并且适用于哪些计算平台？（）","opts":["A. 由Microsoft开发，适用于高性能企业计算平台","B. 由Google开发，适用于桌面计算平台","C. 由Oracle-Sun公司开发，同时适用于高性能企业计算平台、桌面计算平台和移动计算平台","D. 由Apple开发，适用于移动计算平台"],"ans":2,"explain":"Java语言源自Oracle-Sun公司，是一种可同时适用于高性能企业计算平台、桌面计算平台和移动计算平台的计算机编程技术。"},{"id":"java13215-pl-P4085732","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java语言在当今软件开发领域中的地位如何，以及它是哪些人的首选开发语言？（）","opts":["A. Java语言在当今软件开发领域中的地位较低，不被专业开发人员所青睐。","B. Java语言已成为当今最通用、最流行的软件开发语言之一，但只是初学者的首选开发语言。","C. Java语言在当今软件开发领域中的地位一般，被一部分专业开发人员所选择。","D. Java语言已成为当今最通用、最流行的软件开发语言之一，并且是许多专业开发人员的首选开发语言。"],"ans":3,"explain":"Java语言已成为当今最通用、最流行的软件开发语言之一，是许多专业开发人员的首选开发语言。"},{"id":"java13215-pl-P4085733","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java语言可以划分为三大应用品牌，下列哪个不属于其中（）。","opts":["A. Java Plateform Micro Edition（Java ME）","B. Java Plateform Standard Edition （Java SE）","C. Enterprise Java Bean","D. Java Plateform Enterprise Edition （Java EE）"],"ans":2,"explain":"Java语言面向网络应用，主要包含标准版（Java 2 Platform、Standard Edition、Java SE）、面向高性能企业计算的版本（Java 2 Platform、Enterprise Edition、Java EE）和面向高性能移动计算的版本（Java 2 Platform、Micro Edition、Java ME）。"},{"id":"java13215-pl-P4085734","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"JVM是什么类型的计算机？（）","opts":["A. 物理计算机","B. 虚拟计算机","C. 生物计算机","D. 量子计算机"],"ans":1,"explain":"JVM是一台虚拟计算机，是通过在实际的计算机上仿真模拟各种计算机功能来实现的。"},{"id":"java13215-pl-P4085735","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java编译器将Java程序编译成虚拟机能够识别的二进制代码，这种代码称为（）。","opts":["A. 机器码","B. 字节码","C. 汇编代码","D. 高级语言代码"],"ans":1,"explain":"Java编译器将Java程序编译成虚拟机能够识别的二进制代码，这种代码称为字节码（Byte Code）。"},{"id":"java13215-pl-P4085736","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在现在的Java版本中又加入了即时编译功能，即编译器，简称（）。","opts":["A. JIT编译器","B. AOT编译器","C. 解释器","D. 预编译器"],"ans":0,"explain":"在现在的Java版本中又加入了即时编译功能（即Just-In-Time编译器，简称JIT编译器），编译器将字节码转换成本机的机器代码，然后能够以较快速度执行，使得执行效率大幅度提高，基本达到了编译语言的水平。"},{"id":"java13215-pl-P4085737","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java内置了语言级多线程功能，提供现成的类（），只要继承这个类就可以编写多线程的程序，可使用户程序并行执行。","opts":["A. Process","B. Thread","C. Runnable","D. Multithread"],"ans":1,"explain":"Java内置了语言级多线程功能，提供现成的类Thread，只要继承这个类就可以编写多线程的程序，可使用户程序并行执行。"},{"id":"java13215-pl-P4085738","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java解释器是（）。","opts":["A. 用来将Java程序编译成字节码","B. 执行已经转换成字节码的Java程序","C. 用来调试Java程序","D. 将类文件还原回方法和变量"],"ans":1,"explain":"\\bin目录下主要的Java开发工具的用途如下。 （1）javac：Java编译器，用来将Java程序编译成字节码。 （2）java：Java解释器，执行已经转换成字节码的Java程序。 （3）jdb：Java调试器，用来调试Java程序。 （4）javap：反编译，将类文件还原回方法和变量。 （5）javadoc：文档生成器，创建HTML文件。"},{"id":"java13215-pl-P4085739","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java程序文件的扩展名是（）。","opts":["A. .c","B. .java","C. .class","D. .doc"],"ans":1,"explain":"Java程序文件的扩展名是.java，编译后生成的字节码文件的扩展名是.class，需要由JVM载入并解释执行。"},{"id":"java13215-pl-P4085740","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java语言使用（）作为程序运行的入口点。","opts":["A. start()","B. run()","C. main()","D. init()"],"ans":2,"explain":"Java语言使用main（）作为程序运行的入口点。"},{"id":"java13215-pl-P4085741","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"（）关键字说明main方法是公有方法，它可被任何方法访问，包括Java解释器。","opts":["A. public","B. private","C. protected","D. static"],"ans":0,"explain":"public：该关键字说明方法main（）是公有方法，它可被任何方法访问，包括Java解释器。"},{"id":"java13215-pl-P4085742","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"main（）方法的返回值类型是（）。","opts":["A. int","B. void","C. boolean","D. static"],"ans":1,"explain":"void：指明main（）方法不返回任何值。这很重要，因为Java要进行严格的类型检查，包括对调用方法所返回的值的类型和它们说明的类型之间的检查。如果方法没有返回值，则必须说明为void，不可省略；如果方法有返回值，则以返回值类型替换void。"},{"id":"java13215-pl-P4085743","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java源程序文件名要求（）。","opts":["A. 后缀为.java,文件名可以随便取","B. 文件名和类名一样,后缀为.java,大小写没有关系","C. 必须严格与类名完全一致,包括字母大小写,后缀为.java","D. 文件名和后缀均可以随便取,没有限制"],"ans":2,"explain":"读者可以使用系统中提供的文本编辑器，如Windows系统下的记事本，输入程序1.1，并将它存储为文件HelloWorldApp.java。输入时要注意大小写，因为Java语言区分大小写。同时，注意存储的文件名要与类名完全一致。"},{"id":"java13215-pl-P4085744","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"关于Java源文件和执行系统的关系，以下说法正确的是（）。","opts":["A. Java源文件是二进制形式的文件，可以直接被Java执行系统识别和执行。","B. Java源文件是文本形式的文件，可以直接被Java执行系统识别和执行。","C. Java源文件是文本形式的文件，它必须经过编译，生成字节码的类文件后才能运行。","D. Java源文件是二进制形式的文件，它必须经过解释，生成字节码的类文件后才能运行。"],"ans":2,"explain":"源文件是文本形式的文件，Java的执行系统是不能识别的，它必须经过编译，生成字节码的类文件后才能运行。"},{"id":"java13215-pl-P4085745","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"$javac HelloWorldApp.java这里，符号$表示（）。","opts":["A. 命令行","B. 命令解释器","C. 命令提示符","D. 用户权限"],"ans":2,"explain":"$javac HelloWorldApp.java这里，符号$表示命令行提示符，前面可能有系统给出的信息，比如计算机的盘符及目录名。"},{"id":"java13215-pl-P4085746","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Java集成开发环境（IDE）是一个提供给开发人员使用的程序开发环境，下列不属于Java集成开发环境的工具的是（）。","opts":["A. 代码编辑器","B. 编译器","C. 调试器","D. 控制器"],"ans":3,"explain":"IDE是集成开发环境（Integrated Development Environment）的缩写，这是一个提供给开发人员使用的程序开发环境，通常包括了代码编辑器、编译器、调试器和图形用户界面等工具。"},{"id":"java13215-pl-P4085747","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"Eclipse是一款怎样的软件平台？（）","opts":["A. 收费的、基于Python的开发平台","B. 开源的、基于C++的开发平台","C. 开源免费的、基于Java的可扩展开发平台","D. 闭源的、基于Ruby的开发平台"],"ans":2,"explain":"Eclipse是一款开源免费的、基于Java的可扩展开发平台，具体来说，是一个框架和一组服务，通过插件可以构建开发环境。"},{"id":"java13215-pl-P4085748","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"NetBeans是一款用（）编写的开源IDE。","opts":["A. C++","B. Java","C. Python","D. Ruby"],"ans":1,"explain":"NetBeans是一款用Java编写的开源IDE，既可用于Java开发，也支持其他语言，特别是PHP、C/C++和HTML5等。"},{"id":"java13215-pl-P4085749","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"核心API文档的组织方式是怎样的？（）","opts":["A. 按功能分类组织，通过目录结构展示","B. 按字母顺序排列，提供全文搜索功能","C. 按层设计，以主页方式提供给用户，主页按照链接列出包的所有内容","D. 以树状结构展示，每个节点代表一个类或接口"],"ans":2,"explain":"核心API文档是按层设计的，以主页方式提供给用户，主页按照链接列出包的所有内容。"},{"id":"java13215-pl-P4085750","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"下列接口类名正确的是（）。","opts":["A. 错误索引Error Index","B. 异常索引Interface Index","C. 类索引Exception Index","D. 接口索引Class Index"],"ans":0,"explain":"一般地，包页面中都会列有接口索引Interface Index、类索引Class Index、异常索引Exception Index、错误索引Error Index等。"},{"id":"java13215-pl-P4085751","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"面向对象的程序设计方法不包含（）。","opts":["A. 面向对象的分析","B. 面向对象的设计","C. 面向对象的程序设计","D. 面向对象的测试"],"ans":3,"explain":"面向对象方法通常包括三个方面：面向对象的分析（Object-Oriented Analysis，OOA）、面向对象的设计（Object-Oriented Design，OOD）和面向对象的程序设计（Object-Oriented Programming，OOP）。"},{"id":"java13215-pl-P4085752","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"在面向对象编程（OOP）中，对象通常具有哪两方面的特性？（）","opts":["A. 结构和功能","B. 属性和方法","C. 状态和行为","D. 设计和实现"],"ans":2,"explain":"OOP技术把问题看成相互作用的事物的集合，也就是对象的集合。对象具有两方面的特性，一是状态，二是行为。状态是指对象本身的信息，行为是实现对对象的操作。"},{"id":"java13215-pl-P4085753","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"将数据及对数据的操作捆绑在一起成为类，这就是（）技术。","opts":["A. 继承","B. 抽象","C. 多态","D. 封装"],"ans":3,"explain":"将数据及对数据的操作捆绑在一起成为类，这就是封装技术。"},{"id":"java13215-pl-P4085754","type":"sc","tier":"基础","conf":"adapt","chap":"第1章","q":"程序只有一种基本的结构，即（）。","opts":["A. 类","B. 字节","C. 数","D. 字符"],"ans":0,"explain":"程序只有一种基本的结构，即类。"},{"id":"java13215-pl-P4085755","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，不能注释多行内容的符号是（）。","opts":["A. 以//开始的注释","B. 以/*开始，*/结束的注释","C. 以/**开始，*/结束的注释","D. 以%开始的注释"],"ans":0,"explain":"Java中的三种注释形式： （1）从“//”开始一直到行尾均为注释，一般用它对声明的变量、一行程序的作用进行简短说明“//”是注释的开始，行尾表示注释结束。 （2）用于多行注释，“/*”表示注释开始，“*/”表示注释结束，“/*”和“*/”之间的所有内容均是注释内容。这种注释多用来说明方法的功能、设计逻辑及基本思想等。 （3）文档注释，以“/**”开头，以“*/”结束。一般，在公有类定义或公有方法头的前面会使用这样的注释。如果程序中含有这种风格的注释，则可以执行一个称为javadoc的实用程序，提取类头、所有公有方法的头，以及以特定形式写的注释。"},{"id":"java13215-pl-P4085756","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列关于注释的添加方法，正确的是（）。","opts":["A. //用于单行注释，/*...*/用于多行注释，/**...*/是Java所特有的doc注释","B. //用于多行注释，/*...*/用于多行注释，/**...*/是Java所特有的doc注释","C. //用于单行注释，/*...*/也用于单行注释，/**...*/不是Java所特有的doc注释","D. //用于多行注释，/*...*/用于多行注释，/**...*/是Java所特有的doc注释"],"ans":0,"explain":"Java中的三种注释形式： （1）从“//”开始一直到行尾均为注释，一般用它对声明的变量、一行程序的作用进行简短说明“//”是注释的开始，行尾表示注释结束。 （2）用于多行注释，“/*”表示注释开始，“*/”表示注释结束，“/*”和“*/”之间的所有内容均是注释内容。这种注释多用来说明方法的功能、设计逻辑及基本思想等。 （3）文档注释，以“/**”开头，以“*/”结束。一般，在公有类定义或公有方法头的前面会使用这样的注释。如果程序中含有这种风格的注释，则可以执行一个称为javadoc的实用程序，提取类头、所有公有方法的头，以及以特定形式写的注释。"},{"id":"java13215-pl-P4085757","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"注释中以符号（）开头的特定的标签，标识出方法的不同方面。","opts":["A. $","B. %","C. @","D. #"],"ans":2,"explain":"注释中以符号@开头的特定的标签（Tags），标识出方法的不同方面。"},{"id":"java13215-pl-P4085758","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"语句是Java程序的最小执行单位，程序的各语句间以（）分隔。","opts":["A. 逗号","B. 换行","C. 分号","D. 句号"],"ans":2,"explain":"语句是Java程序的最小执行单位，程序的各语句间以分号“；”分隔。"},{"id":"java13215-pl-P4085759","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"Java程序中的语句块是用（ ）包含的。","opts":["A. 大括号","B. 小括号","C. 分号","D. 中括号"],"ans":0,"explain":"大括号“{”和“}”包含的一系列语句称为语句块，简称为块。"},{"id":"java13215-pl-P4085760","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列选项中不是Java关键字的是（）。","opts":["A. class","B. byte","C. varchar","D. import"],"ans":2,"explain":"Java的关键字包括：Abstract、boolean、break、byte、case、cast、catch、char、class、const、continue、default、do、double、else、extends、false、final、finally、float、for、future、generic、goto、if、implements、import、inner、instanceof、int、interface、long、native、new、null、operator、outer、package、private、protected、public、rest、return、short、static、strictfp、super、switch、synchronized、this、throw、throws、transient、true、try、var、void、volatile、while。"},{"id":"java13215-pl-P4085761","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，（）不能作为标识符的开头。","opts":["A. 字母","B. 美元符号","C. 下划线","D. 数字"],"ans":3,"explain":"在Java语言中，标识符是由字母、数字、下划线（_）或美元符号（$）组成的字符串，其中，数字不能作为标识符的开头。"},{"id":"java13215-pl-P4085762","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"关于Java中的标识符，以下说法正确的是（）。","opts":["A. 标识符不区分大小写。","B. 标识符长度有限制。","C. 标识符区分大小写，长度没有限制。","D. 标识符长度有限制，但不区分大小写。"],"ans":2,"explain":"在Java中，标识符区分大小写，长度没有限制。"},{"id":"java13215-pl-P4085763","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"Java源代码使用的是（）。","opts":["A. ASCII码","B. EBCDIC码","C. UTF-8","D. Unicode码"],"ans":3,"explain":"Java源代码使用的是Unicode码，而不是ASCⅡ码。"},{"id":"java13215-pl-P4085764","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"Unicode码用（）位无符号二进制数表示一个字符。","opts":["A. 2","B. 8","C. 10","D. 16"],"ans":3,"explain":"Unicode码用16位无符号二进制数表示一个字符。"},{"id":"java13215-pl-P4085765","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java编程中，类名和接口名的命名规则通常是怎样的？（）","opts":["A. 全部小写，单词之间用空格分隔","B. 全部大写，单词之间用下划线分隔","C. 每个单词的首字母大写，其余小写，单词之间无分隔","D. 每个单词的首字母小写，其余大写，单词之间用连字符分隔"],"ans":2,"explain":"类名或接口名：多为名词，含有大小写，每个单词的首字母大写。"},{"id":"java13215-pl-P4085766","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"以下哪个选项符合Java中类名和接口名的命名规则？（）","opts":["A. my_class_name","B. MyClassName","C. my-class-name","D. MY_CLASS_NAME"],"ans":1,"explain":"类名或接口名：多为名词，含有大小写，每个单词的首字母大写。比如HelloWorld、Customer、SortClass等。"},{"id":"java13215-pl-P4085767","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java编程中，方法名的命名规则通常是怎样的？（）","opts":["A. 全部小写，单词之间用空格分隔","B. 全部大写，单词之间用下划线分隔","C. 首字母大写，其余每个单词的首字母小写，单词之间用连字符分隔","D. 首字母小写，其余每个单词的首字母大写，单词之间无分隔"],"ans":3,"explain":"方法名：多是动词，含有大小写，首字母小写，其余各单词的首字母大写。尽量不要在方法名中使用下划线。方法名如getName、setAddress、searchKey等。"},{"id":"java13215-pl-P4085768","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"以下哪个选项符合Java中方法名的命名规则？（）","opts":["A. getNameOfPerson","B. get_name","C. get name","D. GET_NAME"],"ans":0,"explain":"方法名：多是动词，含有大小写，首字母小写，其余各单词的首字母大写。尽量不要在方法名中使用下划线。方法名如getName、setAddress、searchKey等。"},{"id":"java13215-pl-P4085769","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，数据类型可以分为哪两大类别？（）","opts":["A. 基本数据类型和复合数据类型","B. 简单数据类型和复杂数据类型","C. 内置数据类型和自定义数据类型","D. 静态数据类型和动态数据类型"],"ans":0,"explain":"Java的数据类型分为两大类，一类是基本数据类型，另一类是复合数据类型。"},{"id":"java13215-pl-P4085770","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，以下哪个选项正确描述了基本数据类型的分类？（）","opts":["A. 整型、浮点型、字符型、布尔型","B. 整数型、浮点型、字符串型、布尔型","C. 字符型、布尔型、引用型、数组型","D. 整型、浮点型、逻辑型、字符串型"],"ans":0,"explain":"基本数据类型共有8种，分为4小类，分别是整型、浮点型、字符型和布尔型，整型和浮点型有时也合称为数值型。"},{"id":"java13215-pl-P4085771","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，以下哪个选项不属于基本数据类型的分类？（）","opts":["A. byte","B. short","C. int","D. String"],"ans":3,"explain":"基本数据类型： 整数类型:byte、short、int、long 浮点数类型:float、double 字符类型:char 布尔类型:boolean"},{"id":"java13215-pl-P4085772","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java语言中，以下哪个选项不是复合数据类型？（）","opts":["A. 数组","B. 类","C. 接口","D. 字符串型"],"ans":3,"explain":"复合数据类型包括数组、类和接口。"},{"id":"java13215-pl-P4085773","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下哪个选项正确表示了一个八进制的整型常量？（）","opts":["A. 123","B. 023","C. 0x123","D. 123L"],"ans":1,"explain":"整型常量可用十进制、八进制或十六进制形式表示，以1～9开头的数为十进制数，以0开头的数为八进制数，以0x或0X开头的数为十六进制数。Java中4种整型量都是有符号的。"},{"id":"java13215-pl-P4085774","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下哪个选项正确表示了一个十六进制的整型常量？（）","opts":["A. 123","B. 0123","C. 0x123","D. 123L"],"ans":2,"explain":"整型常量可用十进制、八进制或十六进制形式表示，以1～9开头的数为十进制数，以0开头的数为八进制数，以0x或0X开头的数为十六进制数。Java中4种整型量都是有符号的。"},{"id":"java13215-pl-P4085775","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下哪个选项正确表示了一个十进制的整型常量？（）","opts":["A. 023","B. 0x123","C. 123","D. 077L"],"ans":2,"explain":"整型常量可用十进制、八进制或十六进制形式表示，以1～9开头的数为十进制数，以0开头的数为八进制数，以0x或0X开头的数为十六进制数。Java中4种整型量都是有符号的。"},{"id":"java13215-pl-P4085776","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"八进制数077，等于十进制数（）。","opts":["A. 60","B. 61","C. 62","D. 63"],"ans":3,"explain":"077：表示八进制数77，等于十进制数63。"},{"id":"java13215-pl-P4085777","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下哪个关键字用于声明单精度浮点数类型的变量？（）","opts":["A. int","B. double","C. float","D. long"],"ans":2,"explain":"Java浮点数类型遵从标准的浮点规则。浮点数类型有两种：一种是单精度浮点数，用float关键字说明；另一种是双精度浮点数，用double关键字说明，它们都是有符号数。"},{"id":"java13215-pl-P4085778","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下哪个关键字用于声明双精度浮点数类型的变量？（）","opts":["A. int","B. float","C. double","D. long"],"ans":2,"explain":"Java浮点数类型遵从标准的浮点规则。浮点数类型有两种：一种是单精度浮点数，用float关键字说明；另一种是双精度浮点数，用double关键字说明，它们都是有符号数。"},{"id":"java13215-pl-P4085779","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，关于浮点型常量后面的字母说法正确的是（）。","opts":["A. F或D必须是大写。","B. F或D必须是小写。","C. F或D既可以是大写，也可以是小写。","D. F或D不能使用，应该用f或d。"],"ans":2,"explain":"浮点型常量中的字母F或D既可以是大写，也可以是小写。"},{"id":"java13215-pl-P4085780","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"单个字符用（）类型表示。","opts":["A. int","B. char","C. String","D. float"],"ans":1,"explain":"单个字符用char类型表示。"},{"id":"java13215-pl-P4085781","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，一个char类型的数据用于表示一个Unicode字符，它的值是如何表示的，以及它的取值范围是多少？（）","opts":["A. 使用8位无符号整数，范围为0~255","B. 使用16位无符号整数，范围为0~65535","C. 使用32位无符号整数，范围为0~4294967295","D. 使用16位有符号整数，范围为-32768~32767"],"ans":1,"explain":"一个char表示一个Unicode字符，其值用16位无符号整数表示，范围为0~65535。"},{"id":"java13215-pl-P4085782","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，如何定义一个char类型的常量值？（）","opts":["A. 使用双引号（&quot; &quot;）括起来","B. 使用一对单引号（&#039; &#039;）括起来","C. 使用一对双引号（&quot; &quot;）或单引号（&#039; &#039;）都可以","D. 不需要引号括起来"],"ans":1,"explain":"char类型的常量值必须用一对单引号（‘’）括起来，分为普通字符常量和转义字符常量两种。"},{"id":"java13215-pl-P4085783","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"下列选项中属于换行符的是（）。","opts":["A. &#039;\\b &#039;","B. &#039;\\n&#039;","C. &#039;\\r&#039;","D. &#039;\\t&#039;"],"ans":1,"explain":"\\n&#039;表示换行符。"},{"id":"java13215-pl-P4085784","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，关于数值类型和布尔类型之间的关系，以下哪种说法是正确的？（）","opts":["A. Java允许数值类型和布尔类型之间自由转换。","B. Java是一种严格的类型语言，不允许数值类型和布尔类型之间进行转换。","C. Java允许将布尔值隐式转换为数值类型。","D. Java允许将数值类型隐式转换为布尔类型。"],"ans":1,"explain":"Java是一种严格的类型语言，它不允许数值类型和布尔类型之间进行转换。"},{"id":"java13215-pl-P4085785","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在编程中，表达式是由哪两部分组成的，并对这两部分进行何种操作？（）","opts":["A. 变量和值，对它们进行算术运算","B. 运算符和操作数，对操作数进行运算符指定的操作","C. 函数和参数，对参数进行函数调用","D. 控制流语句和条件，对条件执行控制流操作"],"ans":1,"explain":"表达式由运算符和操作数组成，对操作数进行运算符指定的操作，并得出运算结果。"},{"id":"java13215-pl-P4085786","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，运算符按功能可以分为多种类型，以下哪个选项不属于这些类型？（）","opts":["A. 算术运算符","B. 关系运算符","C. 逻辑运算符","D. 字符串运算符"],"ans":3,"explain":"Java运算符按功能可分为算术运算符、关系运算符、逻辑运算符、位运算符、赋值运算符和条件运算符，除此之外，还有几个特殊用途运算符，如数组下标运算符等。操作数可以是变量、常量或方法调用等。"},{"id":"java13215-pl-P4085787","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，如果表达式包含关系运算符（如“&gt;”），那么该表达式属于什么类型，并且它的计算结果是什么？（）","opts":["A. 算术表达式，结果为整数","B. 逻辑表达式，结果为布尔值","C. 关系表达式，结果为整数","D. 关系表达式，结果为布尔值"],"ans":3,"explain":"如果表达式中含有关系运算符，如“&gt;”，则为关系表达式，它的计算结果是一个逻辑值，即true或false。"},{"id":"java13215-pl-P4085788","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，如果表达式包含逻辑运算符（如“&amp;&amp;”），那么该表达式属于什么类型，并且它的计算结果是什么？（）","opts":["A. 算术表达式，结果为整数","B. 关系表达式，结果为布尔值","C. 逻辑表达式，结果为布尔值","D. 字符串表达式，结果为字符串"],"ans":2,"explain":"如果表达式中含有逻辑运算符，如“&amp;&amp;”，则为逻辑表达式，相应的计算结果为一个逻辑值。"},{"id":"java13215-pl-P4085789","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，关于常量操作数的描述，以下哪个选项是正确的？（）","opts":["A. 常量操作数可以是任意类型的对象。","B. 只有简单数据类型和String类型的常量形式可以在Java中使用。","C. 只有复杂数据类型才有相应的常量形式。","D. 除了String类型，其他类型都不能有常量形式。"],"ans":1,"explain":"常量操作数很简单，只有简单数据类型和String类型才有相应的常量形式。"},{"id":"java13215-pl-P4085790","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，声明变量的位置通常有哪些？（）","opts":["A. 只能在方法内声明变量","B. 只能在类定义内声明变量","C. 既可以在方法内声明变量，也可以在类定义内声明变量","D. 只能在程序的开头声明变量"],"ans":2,"explain":"声明变量的地方有两处，一处是在方法内，另一处是在类定义内。"},{"id":"java13215-pl-P4085791","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，以下关于变量类型的描述哪个是正确的？（）","opts":["A. 方法内定义的变量称为全局变量。","B. 类中定义的变量称为局部变量。","C. 方法内定义的变量称为自动变量或局部变量。","D. 方法内定义的变量称为类的成员变量。"],"ans":2,"explain":"方法内定义的变量称作自动变量，也称为局部变量、临时变量或栈变量。这里所说的方法，包括程序员定义的各个方法。类中定义的变量就是类的成员变量。"},{"id":"java13215-pl-P4085792","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"变量的作用域是指（）。","opts":["A. 变量可以存储的数据类型范围","B. 变量可以执行的操作范围","C. 可访问该变量的代码范围","D. 变量在内存中的存储位置"],"ans":2,"explain":"变量的作用域是指可访问该变量的代码范围。"},{"id":"java13215-pl-P4085793","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，算术运算符用于执行哪些类型的运算？（）","opts":["A. 字符串连接","B. 逻辑判断","C. 整型和浮点型数据的算术运算","D. 变量赋值"],"ans":2,"explain":"算术运算符包括加（+）、减（-）、乘（*）、除（/）、取模（%），完成整型和浮点型数据的算术运算。"},{"id":"java13215-pl-P4085794","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，算术运算符“++”和“--”分别代表什么操作？（）","opts":["A. 前者表示减1操作，后者表示加1操作","B. 前者表示加1操作，后者表示减1操作","C. 两者都表示加1操作","D. 两者都表示减1操作"],"ans":1,"explain":"算术运算符还有“++”和“--”两种，分别称为加1和减1运算符，前者表示加1操作，后者表示减1操作。"},{"id":"java13215-pl-P4085795","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，关系运算符不包括以下哪种比较？（）","opts":["A. 大于（&gt;）","B. 小于或等于（&lt;=）","C. 等于（=）","D. 不等于（!=）"],"ans":2,"explain":"关系运算符用来比较两个值，包括大于（&gt;）、大于或等于（&gt;=）、小于（&lt;）、小于或等于（&lt;=）、等于（==）和不等于（!=）6种。"},{"id":"java13215-pl-P4085796","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，“==”和“!=”运算符可以用于哪种数据类型的运算？（）","opts":["A. 仅限于基本数据类型","B. 仅限于对象类型","C. 任何数据类型","D. 仅限于字符串类型"],"ans":2,"explain":"Java允许“==”和“!=”两种运算用于任何数据类型。"},{"id":"java13215-pl-P4085797","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，逻辑运算符不包括以下哪一项？（）","opts":["A. 逻辑与（&amp;&amp;）","B. 逻辑或（||）","C. 逻辑非（!）","D. 逻辑异或（^）"],"ans":3,"explain":"逻辑运算符包括逻辑与（&amp;&amp;）、逻辑或（Ⅱ）和逻辑非（!）。"},{"id":"java13215-pl-P4085798","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"以下哪个运算符不属于Java中的位运算符？（）","opts":["A. 按位取反（~）","B. 按位与（&amp;）","C. 逻辑或（||）","D. 异或（^）"],"ans":2,"explain":"位运算符用来对二进制位进行操作，包括按位取反（~）、按位与（&amp;）、按位或（｜）、异或（^）、右移（&gt;&gt;）、左移（&lt;&lt;）及无符号右移（&gt;&gt;&gt;）。位运算符只能对整型和字符型数据进行操作。"},{"id":"java13215-pl-P4085799","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，位运算符主要用于处理哪种类型的数据？（）","opts":["A. 浮点型","B. 布尔型","C. 字符串型","D. 整型和字符型"],"ans":3,"explain":"位运算符用来对二进制位进行操作，包括按位取反（~）、按位与（&amp;）、按位或（｜）、异或（^）、右移（&gt;&gt;）、左移（&lt;&lt;）及无符号右移（&gt;&gt;&gt;）。位运算符只能对整型和字符型数据进行操作。"},{"id":"java13215-pl-P4085800","type":"sc","tier":"基础","conf":"adapt","chap":"第2章","q":"在Java中，关于变量类型转换的说法，以下哪项是正确的？（）","opts":["A. Java是一种弱类型语言，支持变量类型间的自动任意转换。","B. Java是一种强类型语言，不支持变量类型间的自动任意转换。","C. Java是一种动态类型语言，变量的类型可以在运行时改变。","D. Java中的变量类型转换总是隐式的，不需要程序员显式声明。"],"ans":1,"explain":"Java是一种强类型语言，不支持变量类型间的自动任意转换，有时必须显式地进行变量类型的转换。"},{"id":"java13215-pl-P4085976","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java是一种功能强大的程序设计语言，既是（）环境，又是（）环境，它代表一种新的计算模式。","opts":[],"ans":null,"explain":"Java是一种功能强大的程序设计语言，既是开发环境，又是应用环境，它代表一种新的计算模式。\n开发，应用"},{"id":"java13215-pl-P4085977","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java是通用的、面向对象的语言，并具有（）、（）和健壮性。","opts":[],"ans":null,"explain":"Java是通用的、面向对象的语言，并具有分布性、安全性和健壮性。\n分布性，安全性"},{"id":"java13215-pl-P4085978","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java它是（）的、动态的语言；最主要的是它与平台无关，解决了困扰软件界多年的软件移植问题。","opts":[],"ans":null,"explain":"Java它是多线程的、动态的语言；最主要的是它与平台无关，解决了困扰软件界多年的软件移植问题。\n多线程"},{"id":"java13215-pl-P4085979","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"简述Java语言的特点。","opts":[],"ans":null,"explain":"（1）语法简单，功能强大，安全可靠<br/>（2）与平台无关<br/>（3）解释编译两种运行方式<br/>（4）多线程<br/>（5）动态执行且有丰富的API文档及类库"},{"id":"java13215-pl-P4085980","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java中没有指针、结构和类型定义等概念，不再有全局变量，没有#include和#define等预处理器，也没有（）的机制。","opts":[],"ans":null,"explain":"Java中没有指针、结构和类型定义等概念，不再有全局变量，没有#include和#define等预处理器，也没有多重继承的机制。\n多重继承"},{"id":"java13215-pl-P4085981","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java是一种（）语言，编写程序时必须严格遵守编程规范，编译程序能够检查出尽可能多的语法错误。","opts":[],"ans":null,"explain":"Java是一种强类型语言，编写程序时必须严格遵守编程规范，编译程序能够检查出尽可能多的语法错误。\n强类型"},{"id":"java13215-pl-P4085982","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java强调面向对象的特性，是一种（）的语言。","opts":[],"ans":null,"explain":"Java强调面向对象的特性，是一种纯面向对象的语言。\n纯面向对象"},{"id":"java13215-pl-P4085983","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java程序通过对象的封装、（）、方法的多态等机制，实现了代码复用、信息隐藏、动态绑定等特性，可以开发出非常复杂的系统，但又不失程序的易读性。","opts":[],"ans":null,"explain":"Java程序通过对象的封装、类的继承、方法的多态等机制，实现了代码复用、信息隐藏、动态绑定等特性，可以开发出非常复杂的系统，但又不失程序的易读性。\n类的继承"},{"id":"java13215-pl-P4085984","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：字节码就是虚拟机的机器指令，它与平台无关，有统一的格式，不依赖于具体的（）环境，只运行在JVM上。","opts":[],"ans":null,"explain":"字节码就是虚拟机的机器指令，它与平台无关，有统一的格式，不依赖于具体的硬件环境，只运行在JVM上。\n硬件"},{"id":"java13215-pl-P4085985","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java语言软件开发工具包是Sun公司（现已被Oracle公司收购）提供的软件包，其中含有编写和运行Java程序的所有工具，包括组成Java环境的基本构件（）、Java解释器java.exe等。","opts":[],"ans":null,"explain":"Java语言软件开发工具包（Java SE Development Kit，JDK）是Sun公司（现已被Oracle公司收购）提供的软件包，其中含有编写和运行Java程序的所有工具，包括组成Java环境的基本构件Java编译器javac.exe、Java解释器java.exe等。\nJava编译器javac.exe"},{"id":"java13215-pl-P4085986","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：编写Java程序的机器上一定要安装（），安装过程中还要正确设置（）和CLASSPATH环境变量，这样系统才能找到javac和java所在的目录，并能正确执行相关命令。","opts":[],"ans":null,"explain":"编写Java程序的机器上一定要安装JDK，安装过程中还要正确设置Path和CLASSPATH环境变量，这样系统才能找到javac和java所在的目录，并能正确执行相关命令。\nJDK，Path"},{"id":"java13215-pl-P4085987","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java程序分为两种，一种是Java应用程序，另一种是Java小应用程序，或叫（）。","opts":[],"ans":null,"explain":"Java程序分为两种，一种是Java应用程序（Java Application），另一种是Java小应用程序（Java Applet），或叫Java小程序。\nJava小程序"},{"id":"java13215-pl-P4085988","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：Java程序由类构成，含有一个main（）方法，称为主方法或（）。","opts":[],"ans":null,"explain":"Java程序由类构成，含有一个main（）方法，称为主方法或主函数。\n主函数"},{"id":"java13215-pl-P4085989","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：目前已有多个开发Java程序的IDE，其中使用较多的有（）和NetBeans。","opts":[],"ans":null,"explain":"目前已有多个开发Java程序的IDE，其中使用较多的有Eclipse和NetBeans。\nEclipse"},{"id":"java13215-pl-P4085990","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：类文档中主要包括类层次结构、类及其一般目的的说明、成员变量表、（）、方法表、变量详细说明表及每一个变量使用目的的详细描述、构造方法的详细说明及进一步的描述、方法的详细说明及进一步的描述。","opts":[],"ans":null,"explain":"类文档中主要包括类层次结构、类及其一般目的的说明、成员变量表、构造函数表、方法表、变量详细说明表及每一个变量使用目的的详细描述、构造方法的详细说明及进一步的描述、方法的详细说明及进一步的描述。\n构造函数表"},{"id":"java13215-pl-P4085991","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：面向对象技术包含的概念主要有抽象、（）、类、类型层次（子类）、封装、继承性、多态性等。","opts":[],"ans":null,"explain":"面向对象技术包含的概念主要有抽象、对象、类、类型层次（子类）、封装、继承性、多态性等。\n对象"},{"id":"java13215-pl-P4085992","type":"sa","tier":"创新","conf":"adapt","chap":"第1章","q":"填空题：OOP中采用了三大技术：（）、继承和多态。","opts":[],"ans":null,"explain":"OOP中采用了三大技术：封装、继承和多态。\n封装"},{"id":"java13215-pl-P4085993","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：Java语言定义了许多关键字，关键字也称为（）。","opts":[],"ans":null,"explain":"Java语言定义了许多关键字，关键字也称为保留字。\n保留字"},{"id":"java13215-pl-P4085994","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：ASCⅡ码字符集通常最多只有（）个。","opts":[],"ans":null,"explain":"Unicode字符集中的字符数可达65536个，比通常使用的ASCⅡ码字符集（通常最多只有256个）大得多。\n256"},{"id":"java13215-pl-P4085995","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：Java语言规范中定义的表示范围用（）来表示，这是独立于平台的。","opts":[],"ans":null,"explain":"Java语言规范中定义的表示范围用2的幂次来表示，这是独立于平台的。\n2的幂次"},{"id":"java13215-pl-P4085996","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：浮点型常量在默认情况下是（）型的。","opts":[],"ans":null,"explain":"浮点型常量在默认情况下是double型的，除非用字母F明确说明它是float型的。\ndouble"},{"id":"java13215-pl-P4085997","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：回车符用（）表示。","opts":[],"ans":null,"explain":"\\r&#039;表示回车符。\n\\r"},{"id":"java13215-pl-P4085998","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：布尔类型也称作（）类型。","opts":[],"ans":null,"explain":"布尔类型也称作逻辑类型。\n逻辑"},{"id":"java13215-pl-P4085999","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：用来声明Java布尔变量（逻辑变量）的关键字是（）。","opts":[],"ans":null,"explain":"用来声明Java布尔变量（逻辑变量）的关键字是boolean。\nboolean"},{"id":"java13215-pl-P4086000","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：变量是（）的基本单元，它可以用作表达式中的操作数。","opts":[],"ans":null,"explain":"变量是存储数据的基本单元，它可以用作表达式中的操作数。\n存储数据"},{"id":"java13215-pl-P4086001","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：变量在使用之前要先（）。","opts":[],"ans":null,"explain":"变量在使用之前要先声明。\n声明"},{"id":"java13215-pl-P4086002","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：在说明简单数据类型的变量之后，系统自动在内存分配相应的存储空间。说明引用后，系统只分配引用空间，程序员要调用（）来创建对象实例，然后才分配相应的存储空间。","opts":[],"ans":null,"explain":"在说明简单数据类型的变量之后，系统自动在内存分配相应的存储空间。说明引用后，系统只分配引用空间，程序员要调用new来创建对象实例，然后才分配相应的存储空间。\nnew"},{"id":"java13215-pl-P4086003","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：Java程序中不允许将未经初始化的变量用作（）。","opts":[],"ans":null,"explain":"Java程序中不允许将未经初始化的变量用作操作数。\n操作数"},{"id":"java13215-pl-P4086004","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：对于自动变量，如果变量声明时没有进行初始化，则在变量使用之前必须使用赋值语句进行（）。","opts":[],"ans":null,"explain":"对于自动变量，如果变量声明时没有进行初始化，则在变量使用之前必须使用赋值语句进行赋值。\n赋值"},{"id":"java13215-pl-P4086005","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：Java语言提供了数学函数类（），其中包含了常用的数学函数，写程序时可以按需调用。","opts":[],"ans":null,"explain":"Java语言提供了数学函数类Math，其中包含了常用的数学函数，写程序时可以按需调用。\nMath"},{"id":"java13215-pl-P4086006","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：关系运算符都是（）运算符，也就是每个运算符都带有两个操作数。","opts":[],"ans":null,"explain":"关系运算符都是二元运算符，也就是每个运算符都带有两个操作数。\n二元"},{"id":"java13215-pl-P4086007","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：128的二进制表示中，最低8位是（）。","opts":[],"ans":null,"explain":"128的二进制表示中，最低8位是1000 0000。\n1000　0000"},{"id":"java13215-pl-P4086008","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：扩展赋值运算符是在赋值号（=）前再加上其他运算符，是对表达式的一种简写形式，赋值号与运算符之间不能加（）。","opts":[],"ans":null,"explain":"扩展赋值运算符是在赋值号（=）前再加上其他运算符，是对表达式的一种简写形式，赋值号与运算符之间不能加空格。\n空格"},{"id":"java13215-pl-P4086009","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"填空题：在对一个表达式进行计算时，如果表达式中含有多个运算符，则要按运算符的优先顺序依次从高向低进行，同级运算符则根据结合律（）或从右向左进行。","opts":[],"ans":null,"explain":"在对一个表达式进行计算时，如果表达式中含有多个运算符，则要按运算符的优先顺序依次从高向低进行，同级运算符则根据结合律从左向右或从右向左进行。\n从左向右"},{"id":"java13215-pl-P4086010","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述Java中的运算符有哪几类？请每类列出几个。","opts":[],"ans":null,"explain":"Java中的运算符有5类，分别为：<br/>（1）算术运算符。包括加（+）、减（-）、乘（*）、除（/）、取模（%）。<br/>（2）关系运算符。用来比较两个值，包括大于（&gt;）、大于或等于（&gt;=）、小于（&lt;）、小于或等于（&lt;=）、等于（==）和不等于（!=）6种。<br/>（3）逻辑运算符。包括逻辑与（&amp;&amp;）、逻辑或（Ⅱ）和逻辑非（!）。<br/>（4）位运算符。包括按位取反（~）、按位与（&amp;）、按位或（｜）、异或（^）、右移（&gt;&gt;）、左移（&lt;&lt;）及无符号右移（&gt;&gt;&gt;）。<br/>（5）其他运算符。包括扩展赋值运算符（+=、-=、*=、/=、%=、&amp;=、|=、^=、&gt;&gt;=、&lt;&lt;=和&gt;&gt;&gt;=）、条件运算符（？:）、点运算符（.）、实例运算符（instanceof）、new运算符及数组下标运算符（[]）。"},{"id":"java13215-pl-P4086011","type":"sa","tier":"创新","conf":"adapt","chap":"第2章","q":"简述二元逻辑运算中的“短路”操作功能。","opts":[],"ans":null,"explain":"进行运算时，先计算运算符左侧表达式的值，如果使用该值能得到整个表达式的值，则跳过运算符右侧表达式的计算，否则计算运算符右侧表达式，并得到整个表达式的值。"},{"id":"java13215-pl-P4085961","type":"sa","tier":"拔高","conf":"adapt","chap":"第2章","q":"程序分析题：读程序，控制台运行结果是什么？ int a = 10； int b =20； int c= a +b； int d= a -b； System.out.println(&quot;c =&quot;+c)； System.out.println(&quot;d =&quot;+d)；","opts":[],"ans":null,"explain":"c=30,d=-10"},{"id":"java13215-pl-P4085801","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java程序中，关于package语句的使用，以下哪个说法是正确的？（）","opts":["A. package语句可以出现在源文件中的任何位置。","B. 一个Java源文件中可以有多个package语句。","C. package语句必须是源文件中的第一条非注释语句，其前面只能有注释或空行。","D. package语句后面必须紧跟一个分号。"],"ans":2,"explain":"程序中如果有package语句，该语句一定是源文件中的第一条非注释语句，它的前面只能有注释或空行。另外，一个文件中最多只能有一条package语句。"},{"id":"java13215-pl-P4085802","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"包的名字有层次关系，各层之间以（）分隔。","opts":["A. 空格","B. 下划线","C. 点","D. 斜杠"],"ans":2,"explain":"包的名字有层次关系，各层之间以点分隔。"},{"id":"java13215-pl-P4085803","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java编程语言中，哪个符号用于分隔不同的语句？（）","opts":["A. 逗号","B. 分号","C. 冒号","D. 点号"],"ans":1,"explain":"语句是Java的最小执行单位，语句间以分号（；）作为分隔符。"},{"id":"java13215-pl-P4085804","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java程序中，以下哪种语句用于将表达式的值赋给变量？（）","opts":["A. 声明语句","B. 赋值语句","C. 条件语句","D. 循环语句"],"ans":1,"explain":"在Java程序中，表达式可以当作一个值赋给某个变量，这样的语句称为赋值语句。"},{"id":"java13215-pl-P4085805","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，分支语句主要包括哪两种类型？（）","opts":["A. if语句和for语句","B. switch语句和while语句","C. if语句和switch语句","D. do-while语句和try-catch语句"],"ans":2,"explain":"分支语句根据一定的条件，动态决定程序的流程方向，从程序的多个分支中选择一个或几个来执行。分支语句有if语句和switch语句两种。"},{"id":"java13215-pl-P4085806","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"if语句是单重选择，最多只有（）个分支。","opts":["A. 1","B. 2","C. 3","D. 4"],"ans":1,"explain":"if语句是单重选择，最多只有两个分支。"},{"id":"java13215-pl-P4085807","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"关于Java中for语句的语义，以下哪个描述是正确的？（）","opts":["A. 先执行循环体，然后判断条件表达式的值。","B. 先判断条件表达式的值，然后执行初始语句。","C. 先执行初始语句，然后判断条件表达式的值。","D. 循环体、初始语句和条件表达式是并行执行的。"],"ans":2,"explain":"for语句的语义是：先执行初始语句，判断条件表达式的值。"},{"id":"java13215-pl-P4085808","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，break语句可以在哪些类型的语句中使用？（）","opts":["A. 仅在switch语句中","B. 仅在循环语句（如for、while、do-while）中","C. 在switch语句和循环语句（如for、while、do-while）中","D. 在switch语句、循环语句（如for、while、do-while）以及语句块中"],"ans":3,"explain":"break语句可用于三类语句中，第一类是在switch语句中，第二类是在for、while及do-while等循环语句中，第三类是在语句块中。"},{"id":"java13215-pl-P4085809","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，Scanner对象使用哪些字符作为输入的分隔符？（）","opts":["A. 仅使用空格作为分隔符","B. 仅使用制表符作为分隔符","C. 仅使用回车换行符作为分隔符","D. 使用空格、水平制表符及回车换行符作为分隔符"],"ans":3,"explain":"Scanner对象用空白（空格、水平制表符及回车换行符）作为输入的分隔元素，这些空白称为分隔符。也可以指定用其他的符号作为分隔符。"},{"id":"java13215-pl-P4085810","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，Scanner类的next()方法的作用是（）。","opts":["A. 读取用户输入的下一个字符，并返回它。","B. 读取用户输入的下一个单词，并返回它。","C. 读取用户输入的下一行文本，并返回它。","D. 读取用户输入的下一个输入对象，并作为字符串返回。"],"ans":3,"explain":"Scanner类的next（）方法用于读入下一个输入对象，将它作为字符串返回。"},{"id":"java13215-pl-P4085811","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，关于异常处理机制的说法，以下哪项是正确的？（）","opts":["A. Java没有提供任何异常处理机制。","B. Java中的异常处理机制是通过预定义的Exception类来实现的。","C. Exception类是Java中唯一用于处理异常的类。","D. Java的异常处理机制是通过使用try-catch块来实现的。"],"ans":1,"explain":"为了解决异常问题，Java提供了异常处理机制，预定义了Exception类。"},{"id":"java13215-pl-P4085812","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，生成异常对象并把它提交给运行时系统的过程被称为（）。","opts":["A. 捕获异常","B. 声明异常","C. 抛出异常","D. 处理异常"],"ans":2,"explain":"生成异常对象并把它提交给运行时系统的过程称为抛出（Throw）一个异常。"},{"id":"java13215-pl-P4085813","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，运行时系统从生成异常对象的代码块开始回溯，沿着方法的调用栈逐层搜索，以寻找包含相应异常处理代码块的过程，称为（）。","opts":["A. 捕获异常","B. 声明异常","C. 抛出异常","D. 处理异常"],"ans":0,"explain":"Java运行时系统从生成对象的代码块开始进行回溯，沿方法的调用栈逐层回溯，寻找相应的处理代码，直到找到包含相应异常处理的方法为止，并把异常对象交给该方法处理。这一过程称为捕获（Catch）。"},{"id":"java13215-pl-P4085814","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，受检异常指的是（）。","opts":["A. 程序执行期间发生的严重事件的后果。","B. 程序设计错误导致的异常。","C. 运行时环境错误导致的异常。","D. 程序员必须隐式处理或声明的异常。"],"ans":0,"explain":"受检异常（Checked Exception）是程序执行期间发生的严重事件的后果。"},{"id":"java13215-pl-P4085815","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java类库中，哪个类表示受检异常（Checked Exception）？（）","opts":["A. ClassNotFoundException","B. FileNotFoundException","C. IOException","D. NoSuchMethodException"],"ans":1,"explain":"在Java类库中，FileNotFoundException是一个受检异常，它继承自IOException类。当应用程序试图打开一个不存在的文件时，Java运行时环境会抛出这个异常。由于它是IOException的子类，并且需要在编译时进行处理或声明，因此它是受检异常。"},{"id":"java13215-pl-P4085816","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"下列选项中属于Java类库中的受检异常的是（）。","opts":["A. IOException","B. ArithmeticException","C. ArrayIndexOutOfBoundsException","D. ClassCast Exception"],"ans":0,"explain":"Java类库中的下列类表示受检异常：ClassNotFoundException、FileNotFoundException、IOException、NoSuchMethodException及WriteAbortedException。"},{"id":"java13215-pl-P4085817","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"下列选项中不属于Java类库中的运行时异常的是（）。","opts":["A. EmptyStackException","B. IllegalStateException","C. IndexOutOfBoundsException","D. FileNotFoundException"],"ans":3,"explain":"Java类库中的下列类表示运行时异常：ArithmeticException、ArrayIndexOutOfBoundsException、ClassCast Exception、EmptyStackException、IllegalArgumentException、IllegalStateException、IndexOutOfBoundsException、NoSuchElementException、NullPointerException和UnsupportedOperationException。"},{"id":"java13215-pl-P4085818","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"运行时异常（Runtime Exception）通常是以下哪种情况的结果？（）","opts":["A. 程序编译时的语法错误","B. 程序执行时的硬件故障","C. 程序执行时的逻辑错误","D. 程序设计时的架构问题"],"ans":2,"explain":"运行时异常（Runtime Exception）通常是程序中逻辑错误的结果。"},{"id":"java13215-pl-P4085819","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，运行时异常和错误被统称为（）。","opts":["A. 已检异常（Checked Exception）","B. 不检异常（Unchecked Exception）","C. 系统异常（System Exception）","D. 自定义异常（Custom Exception）"],"ans":1,"explain":"运行时异常和错误称为不检异常（Unchecked Exception）。"},{"id":"java13215-pl-P4085820","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Java中，处理异常的代码结构通常包含哪两部分？（）","opts":["A. try块和finally块","B. catch块和finally块","C. try块和catch块","D. try块、catch块和finally块"],"ans":2,"explain":"处理异常的代码有两段，第一段try块含有可能抛出异常的语句；第二段含有一个或多个catch块，每个catch块包括捕获及处理某种类型异常的代码。"},{"id":"java13215-pl-P4085821","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"如果在保护代码内执行了（）方法，将不执行finally后面的语句，这是不执行finally后面语句的唯一一种可能。","opts":["A. System.skip（）","B. System.goto（）","C. System.loop（）","D. System.exit（）"],"ans":3,"explain":"如果在保护代码内执行了System.exit（）方法，将不执行finally后面的语句，这是不执行finally后面语句的唯一一种可能。"},{"id":"java13215-pl-P4085822","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"如果一个对象还没有实例化，那么访问该对象或调用它的方法将导致（）异常。","opts":["A. ArithmeticException","B. NullPointerException","C. NegativeArraySizeException","D. ArrayIndexOutOfBoundsException"],"ans":1,"explain":"如果一个对象还没有实例化，那么访问该对象或调用它的方法将导致NullPointerException异常。"},{"id":"java13215-pl-P4085823","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"创建数组时，如果元素个数是负数，则会引发（）异常。","opts":["A. ArithmeticException","B. NullPointerException","C. NegativeArraySizeException","D. ArrayIndexOutOfBoundsException"],"ans":2,"explain":"按常规，数组的元素个数应是一个大于或等于0的整数。创建数组时，如果元素个数是负数，则会引发NegativeArraySizeException异常。"},{"id":"java13215-pl-P4085824","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"类定义中的修饰符是访问权限修饰符，其中不包含（）。","opts":["A. private","B. protected","C. public","D. class"],"ans":3,"explain":"类定义中的修饰符是访问权限修饰符，包括public、private和protected，也可以不写，表示是默认修饰符。"},{"id":"java13215-pl-P4085825","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于类定义，下列描述不正确的是（）。","opts":["A. 类头与类体是放在一起保存的","B. 源文件名要区分大小写","C. 类定义中必须指明父类","D. class定义的大括号之后没有分隔符"],"ans":2,"explain":"关于类定义，总结如下。 （1）类定义中，类头与类体是放在一起保存的，整个类必须在一个文件中，因此有时源文件会很大。 （2）源文件名必须根据文件中的公有类名来定义，并且要区分大小写。 （3）类定义中可以指明父类，也可以不指明。若没有指明从哪个类派生而来，则表明是从默认的父类Object派生而来。实际上，Object是Java所有类的直接或间接父类。Java中除Object之外的所有类均有一个且仅有一个父类。Object是唯一没有父类的类。 （4）class定义的大括号之后没有分隔符“；”。"},{"id":"java13215-pl-P4085826","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于构造方法（Constructor），以下哪个说法是正确的？（）","opts":["A. 构造方法允许程序员像普通方法一样直接调用。","B. 构造方法用于创建类的实例，并且在生成实例时由系统自动调用。","C. 构造方法不能被覆盖（Override）。","D. 构造方法必须声明为public。"],"ans":1,"explain":"构造方法是用来创建类的实例的，一般不允许程序员按通常调用方法的方式来调用，它只用于生成实例时由系统自动调用。它们具有以下特点： 构造方法的名称必须与类的名称完全相同。 构造方法没有返回类型，连void也没有。 构造方法在创建类的实例时由系统自动调用，并且不允许程序员像普通方法一样直接调用。 构造方法不能被继承，因此也不能被覆盖（Override）。 构造方法的访问修饰符可以是public、protected、private或默认（无修饰符），具体取决于你想如何限制对类实例的创建。"},{"id":"java13215-pl-P4085827","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"构造方法通常说明为（）类型的。","opts":["A. final","B. native","C. abstract","D. public"],"ans":3,"explain":"构造方法不能说明为native、abstract、synchronized或final类型，通常说明为public类型的。"},{"id":"java13215-pl-P4085828","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于默认构造方法，以下哪个说法是正确的？（）","opts":["A. 默认构造方法的参数列表为空，但方法体不为空。","B. 默认构造方法生成的对象的所有属性值均不为零或空。","C. 默认构造方法的参数列表和方法体均为空，但所生成的对象的属性值不一定为零或空。","D. 默认构造方法的参数列表和方法体均为空，所生成的对象的各属性值也为零或空。"],"ans":3,"explain":"默认构造方法的参数列表及方法体均为空，所生成的对象的各属性值也为零或空。"},{"id":"java13215-pl-P4085829","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在Java中，对于声明为private的成员变量，以下哪个说法是正确的？（）","opts":["A. 可以在类外通过点操作符直接访问。","B. 可以在类外通过任何方式直接访问。","C. 不能在类外直接访问，但可以通过反射机制来访问。","D. 不能在类外直接访问，必须通过成员方法才能访问。"],"ans":3,"explain":"声明为private的成员变量，在类外，不能通过点操作符直接访问，必须通过成员方法才能访问。"},{"id":"java13215-pl-P4085830","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在Java中，如果方法不返回任何值，则应该声明为（）。","opts":["A. int","B. double","C. void","D. String"],"ans":2,"explain":"返回值类型是方法返回值的类型。如果方法不返回任何值，则应该声明为void。"},{"id":"java13215-pl-P4085831","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"允许多个方法使用同一个方法名，这就是方法名的（）。","opts":["A. 重载","B. 隐藏","C. 重写","D. 继承"],"ans":0,"explain":"允许多个方法使用同一个方法名，这就是方法名的重载（Overload）。"},{"id":"java13215-pl-P4086012","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：一个Java程序可以由一个或多个.java文件组成，这些文件称为（）。","opts":[],"ans":null,"explain":"一个Java程序可以由一个或多个.java文件组成，这些文件称为源文件。\n源文件"},{"id":"java13215-pl-P4086013","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：如果一个源文件中有多个类，则最多只能有一个是（）类型的类。","opts":[],"ans":null,"explain":"每个源文件中含有一个或多个类或接口。如果一个源文件中有多个类，则最多只能有一个是public类型的类，且该源文件的名字即为该public类的名字，大小写也要一致。其他非public的类的个数不限。\npublic"},{"id":"java13215-pl-P4086014","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：包层次必须与Java开发系统的（）结构相同。","opts":[],"ans":null,"explain":"包层次必须与Java开发系统的文件系统结构相同。\n文件系统"},{"id":"java13215-pl-P4086015","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：由于Java使用文件系统来存储包和类，故类名就是文件名，包名就是文件夹名，即（）。","opts":[],"ans":null,"explain":"由于Java使用文件系统来存储包和类，故类名就是文件名，包名就是文件夹名，即目录名。\n目录名"},{"id":"java13215-pl-P4086016","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：复合语句是一对大括号（“{”和“}”）括起来的语句组，也称为“（）”。","opts":[],"ans":null,"explain":"复合语句是一对大括号（“{”和“}”）括起来的语句组，也称为“块”。\n块"},{"id":"java13215-pl-P4086017","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：Java规定switch语句不允许使用（）或long型表达式。","opts":[],"ans":null,"explain":"Java规定switch语句不允许使用浮点型或long型表达式。\n浮点型"},{"id":"java13215-pl-P4086018","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"程序填空题：请填写下面的程序，使其能够正确地计算并返回给定月份的天数。 static int daysInMonth(int month){ int days; if (month&lt;=0 || month 12) ①; switch(month){ case 2: days =28; break; case 4:case 6:case 9:case 11: days 30; break; default: ②; } return days; }","opts":[],"ans":null,"explain":"①return　-1<br/>②days　31"},{"id":"java13215-pl-P4086019","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"请写出用if语句实现计算y=|x-5|的代码。","opts":[],"ans":null,"explain":"if(x-5&lt;0)<br/>　y=5-x;<br/>else<br/>　y=x-5;"},{"id":"java13215-pl-P4086020","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：for语句括号内的3个部分都是可选的，条件表达式为空时，默认规定为（）。","opts":[],"ans":null,"explain":"for语句括号内的3个部分都是可选的，条件表达式为空时，默认规定为恒真。\n恒真"},{"id":"java13215-pl-P4086021","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述while语句的语义。","opts":[],"ans":null,"explain":"while语句的语义是：计算条件表达式的值，当值为真时，重复执行循环体语句，直到条件表达式为假时结束。如果第一次检查时条件表达式为假，则循环体语句一次也不执行。如果条件表达式始终为真，则循环不会终止。"},{"id":"java13215-pl-P4086022","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：do-while语句无论条件表达式的值是真是假，do循环中的循环体都至少执行（）次。","opts":[],"ans":null,"explain":"do-while语句的语义是：首先执行循环体语句，然后判别条件表达式的值，当值为真时，重复执行循环体语句，直到表达式的值为假时结束循环。无论条件表达式的值是真是假，do循环中的循环体都至少执行一次。\n一"},{"id":"java13215-pl-P4086023","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：（）语句和continue语句可以用在分支语句或循环语句中，让程序员更方便地控制程序执行的方向。","opts":[],"ans":null,"explain":"break语句和continue语句可以用在分支语句或循环语句中，让程序员更方便地控制程序执行的方向。\nbreak"},{"id":"java13215-pl-P4086024","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：在循环语句中，（）语句可以立即结束当次循环，开始执行下一次循环，当然执行前要先判断循环条件是否满足。","opts":[],"ans":null,"explain":"在循环语句中，continue语句可以立即结束当次循环，开始执行下一次循环，当然执行前要先判断循环条件是否满足。\ncontinue"},{"id":"java13215-pl-P4086025","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：Scanner类属于（）包。","opts":[],"ans":null,"explain":"Scanner类属于java.util包。\njava.util"},{"id":"java13215-pl-P4086026","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：Scanner类的构造方法接收一个参数，这个参数代表了输入源。System.in对象代表标准输入流，默认是指（）。","opts":[],"ans":null,"explain":"Scanner类的构造方法接收一个参数，这个参数代表了输入源。System.in对象代表标准输入流，默认是指键盘。\n键盘"},{"id":"java13215-pl-P4086027","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"程序填空题：请填写下面的程序，使其能够正常运行程序并以字符串返回。 import ①; public class Echo{ public static void main(String[] args){ String message; Scanner scan = new Scanner(System.in); System.out.println(&quot;Enter a line of text:&quot;); message = scan. ② ; System.out.println(&quot;You entered: \\&quot;&quot; + message + &quot;\\&quot;&quot;); } }","opts":[],"ans":null,"explain":"①java.util.Scanner<br/>②nextLine()"},{"id":"java13215-pl-P4086028","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"程序填空题：阅读下面代码，如果输入的数字是6，输出正确的运行结果。 import java.util.&quot;; public class Test{ public static void main(String[] args){ Scanner in = new ① ; System.out.print(请输入1个1~10之间的数:&quot;); int num=in. ② ; for(int i=1;i&lt;=10;i++){ if((i+num)&gt;10){ break; } System.out.print(i+&quot;\\t&quot;); } } }","opts":[],"ans":null,"explain":"①Scanner(System.in)<br/>②nextlnt()"},{"id":"java13215-pl-P4086029","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述NumberFormat类中常用的方法。","opts":[],"ans":null,"explain":"NumberFormat类中常用的方法如下。<br/>（1）getlnstance（）（2）getCurencyInstance（）<br/>（3）getNumberlnstance（）<br/>（4）getPercentInstance（）<br/>（5）setMaximumFractionDigits（int）<br/>（6）setMaximumIntegerDigits（int）<br/>（7）setMinimumFractionDigits（int）<br/>（7）setMinimumIntegerDigits（int）"},{"id":"java13215-pl-P4086030","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：DecimalFormat类属于Java标准类库，定义在（）包中。","opts":[],"ans":null,"explain":"DecimalFormat类属于Java标准类库，定义在java.text包中。\njava.text"},{"id":"java13215-pl-P4086031","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：NumberFormat类提供对数值进行格式化操作的一般功能。不能使用new运算符实例化一个NumberFormat对象，只能直接使用类名调用一个特殊的（）方法来得到一个对象。","opts":[],"ans":null,"explain":"NumberFormat类提供对数值进行格式化操作的一般功能。不能使用new运算符实例化一个NumberFormat对象，只能直接使用类名调用一个特殊的静态方法来得到一个对象。\n静态"},{"id":"java13215-pl-P4086032","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：DecimalFormat类按惯例使用new运算符来实例化对象。它的构造方法要带一个（）类型的参数，这个参数表示格式化处理模式。","opts":[],"ans":null,"explain":"DecimalFormat类按惯例使用new运算符来实例化对象。它的构造方法要带一个String类型的参数，这个参数表示格式化处理模式。\nString"},{"id":"java13215-pl-P4086033","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：Exception类是所有异常类的父类，Error类是所有错误类的父类，这两个类同时又是（）类的子类。","opts":[],"ans":null,"explain":"Exception类是所有异常类的父类，Error类是所有错误类的父类，这两个类同时又是Throwable类的子类。\nThrowable"},{"id":"java13215-pl-P4086034","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：Throwable在Java类库中，不需要（）语句就可以使用。","opts":[],"ans":null,"explain":"Throwable在Java类库中，不需要import语句就可以使用。\nimport"},{"id":"java13215-pl-P4086035","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述3种异常。","opts":[],"ans":null,"explain":"（1）受检异常，必须被处理。<br/>（2）运行时异常，不需要处理。<br/>（3）错误，不需要处理。"},{"id":"java13215-pl-P4086036","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：运行时异常的所有类都是（）类的子类，它是Exception类的后代。","opts":[],"ans":null,"explain":"运行时异常的所有类都是RuntimeException类的子类，它是Exception类的后代。\nRuntimeException"},{"id":"java13215-pl-P4086037","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：catch块的语法类似于一个方法定义。标识符e称为catch块（），它表示catch块将要处理的IOException对象。","opts":[],"ans":null,"explain":"catch块的语法类似于一个方法定义。标识符e称为catch块参数，它表示catch块将要处理的IOException对象。\n参数"},{"id":"java13215-pl-P4086038","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"填空题：try后大括号中的代码称为（）。","opts":[],"ans":null,"explain":"try后大括号中的代码称为保护代码。\n保护代码"},{"id":"java13215-pl-P4086039","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：类的定义也称为类的（）。","opts":[],"ans":null,"explain":"类的定义也称为类的声明。\n声明"},{"id":"java13215-pl-P4086040","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：类中含有两部分，分别是数据成员变量和（）。","opts":[],"ans":null,"explain":"类中含有两部分，分别是数据成员变量和成员方法。\n成员方法"},{"id":"java13215-pl-P4086041","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述类是如何定义的？","opts":[],"ans":null,"explain":"关于类定义，总结如下：<br/>（1）类定义中，类头与类体是放在一起保存的，整个类必须在一个文件中，因此有时源文件会很大；<br/>（2）源文件名必须根据文件中的公有类名来定义，并且要区分大小写；<br/>（3）类定义中可以指明父类，也可以不指明。若没有指明从哪个类派生而来，则表明是从默认的父类Object派生而来。实际上，Object是Java所有类的直接或间接父类。Java中除Object之外的所有类均有一个且仅有一个父类。Object是唯一没有父类的类；<br/>（4）class定义的大括号之后没有分隔符“；”。"},{"id":"java13215-pl-P4086042","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：构造方法的名字与（）相同，没有返回值，在创建对象实例时通过new运算符自动调用。","opts":[],"ans":null,"explain":"构造方法的名字与类名相同，没有返回值，在创建对象实例时通过new运算符自动调用。\n类名"},{"id":"java13215-pl-P4086043","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：为了便于创建实例，一个类可以有多个具有不同参数列表的构造方法，即构造方法可以（）。","opts":[],"ans":null,"explain":"同时为了便于创建实例，一个类可以有多个具有不同参数列表的构造方法，即构造方法可以重载。\n重载"},{"id":"java13215-pl-P4086044","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：构造方法不能从（）继承。","opts":[],"ans":null,"explain":"构造方法不能从父类继承。另外，构造方法没有返回值类型。\n父类"},{"id":"java13215-pl-P4086045","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：一般来讲，构造方法应该为所有的成员变量赋初值，成员变量的值亦称为（）。","opts":[],"ans":null,"explain":"一般来讲，构造方法应该为所有的成员变量赋初值，成员变量的值亦称为对象的属性值。\n对象的属性值"},{"id":"java13215-pl-P4086046","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：在类定义的方法中，Java自动用（）关键字把所有变量和方法引用结合在一起。","opts":[],"ans":null,"explain":"在类定义的方法中，Java自动用this关键字把所有变量和方法引用结合在一起。\nthis"},{"id":"java13215-pl-P4086047","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：对象的引用也称为（）。","opts":[],"ans":null,"explain":"声明变量后，在内存中为其建立了一个引用，此时它不指向任何内存空间。对象的引用也称为对象的句柄。\n对象的句柄"},{"id":"java13215-pl-P4086048","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：用class类型声明的变量并不是对象本身，而只是对对象的引用，进一步要用new来创建类的对象，对象也称为（）。","opts":[],"ans":null,"explain":"换句话说，用class类型声明的变量并不是对象本身，而只是对对象的引用，进一步要用new来创建类的对象，对象也称为实例。\n实例"},{"id":"java13215-pl-P4086049","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：在Java中，使用构造方法是生成实例对象的唯一途径，这个过程称为对象的（）。","opts":[],"ans":null,"explain":"在Java中，使用构造方法是生成实例对象的唯一途径，这个过程称为对象的实例化。\n实例化"},{"id":"java13215-pl-P4086050","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：参数列表是传送给方法的参数表。表中各元素间以逗号分隔，每个元素由一个类型和一个（）表示的参数组成。","opts":[],"ans":null,"explain":"参数列表是传送给方法的参数表。表中各元素间以逗号分隔，每个元素由一个类型和一个标识符表示的参数组成。\n标识符"},{"id":"java13215-pl-P4086051","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：调用方法时，通常会给方法传递一些值。传给方法的值称为（），方法的参数列表中列出的各元素称为形参。","opts":[],"ans":null,"explain":"调用方法时，通常会给方法传递一些值。传给方法的值称为实参，方法的参数列表中列出的各元素称为形参。\n实参"},{"id":"java13215-pl-P4086052","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：一般，方法名称加上方法的参数列表（包括方法中参数的个数、顺序和类型）称为（）。","opts":[],"ans":null,"explain":"一般，方法名称加上方法的参数列表（包括方法中参数的个数、顺序和类型）称为方法签名。\n方法签名"},{"id":"java13215-pl-P4086053","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述重载方法的两条规则。","opts":[],"ans":null,"explain":"（1）调用语句的实参列表必须足够判断要调用的是哪个方法。实参的类型可能要进行正常的扩展提升（如浮点数变为双精度数），但在有些情况下会引起混淆。<br/>（2）方法的返回值类型可以相同也可以不同。两个同名方法仅返回值类型不同，而参数列表完全相同，这是不够的，因为在方法执行前不知道能得到什么类型的返回值，因此也就不能确定要调用哪个方法。重载方法的参数列表必须不同。"},{"id":"java13215-pl-P4085962","type":"sa","tier":"拔高","conf":"adapt","chap":"第3章","q":"程序分析题：下面程序的执行结果是什么？ public class Weather{ public static void main(String[] args){ int shiDu=45; if(shiDu &gt;=80){ System.out.println(&quot;要下雨了&quot;); }else if(shiDu &gt;=50){ System.out.printIn(&quot;天很阴&quot;); }else if(shiDu &gt;=30){ System..out.println(&quot;很舒适&quot;); }else if(shiDu &gt;=0){ System..out.println(&quot;很干燥&quot;); } } }","opts":[],"ans":null,"explain":"很舒适"},{"id":"java13215-pl-P4085963","type":"sa","tier":"拔高","conf":"adapt","chap":"第3章","q":"程序分析题：阅读下面代码，如果输入的数字是6，正确的运行结果是什么。 import java.util.&quot;; public class Test{ public static void main(String[] args){ Scanner in = new Scanner(System.in); System.out.print(请输入1个1~10之间的数:&quot;); int num=in.nextlnt(); for(int i=1;i&lt;=10;i++){ if((i+num)&gt;10){ break; } System.out.print(i+&quot;\\t&quot;); } } }","opts":[],"ans":null,"explain":"1　　2　　　3　　　4"},{"id":"java13215-pl-P4085964","type":"calc","tier":"创新","conf":"adapt","chap":"第3章","q":"程序设计题：求100以内能被3整除的数。 public class test{ public static void main(String[] args)( int sum=0; //请在此处填写应编写的代码 System.out.println(sum); } }","opts":[],"ans":null,"explain":"for(int　i=0;i&lt;100;i++)(<br/>　　if(i%3==0){<br/>　　　sum=sum+i;<br/>　　}<br/>　}"},{"id":"java13215-pl-P4085965","type":"calc","tier":"创新","conf":"adapt","chap":"第3章","q":"程序设计题：编写一个程序，实现的功能是：从控制台或对话框输入 5 个学生的成绩（成绩取值范围：0~100），存放在一个一维数 组中，判断其等级，存放在另一个一维数组中，等级判断标准：大于或等于 90 为“优秀”； 大于 或等于 80，且小于 90 为“良好”； 大于或等于 60，且小于 80 为“及格”； 小于 60 为“不及格”， 并从控制台输出。（要求使用多分支switch） public class StudentScore1{ public static void main(String[] args){ int[] score=new int[5]; String[] range=new String[5]; Scanner input=new Scanner(System.in); for (int i=0;i&lt;score.length:i++){ score[i]=Integer.parseInt (JOptionPane.showInputDialog(&quot;第&quot;+(i+1)+&quot;个成绩是：&quot;)); } for (int i =0;i&lt;score.length;i++){ //请在此处填写应编写的代码 }","opts":[],"ans":null,"explain":"switch　(score[i]/10){<br/>　　case　10:<br/>　　case　9:<br/>　　　range[i]=优秀&quot;;<br/>　　　break:<br/>　　case　8:<br/>　　　range[i]=&quot;良好&quot;;<br/>　　　break;<br/>　　case　7:<br/>　　case　6:<br/>　　　range[i]=&quot;及格&quot;：<br/>　　　break;<br/>　　default:<br/>　　　range[i]=&quot;不及格&quot;：<br/>　}"},{"id":"java13215-pl-P4085832","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在类的定义中还可以定义一种特殊的成员，用（）修饰，称为静态成员或类成员。","opts":["A. String value","B. different","C. Overload","D. static"],"ans":3,"explain":"在类的定义中还可以定义一种特殊的成员，用static修饰，称为静态成员或类成员，包括静态变量和静态方法。"},{"id":"java13215-pl-P4085833","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"（）是唯一为类中所有对象共享的变量。","opts":["A. 静态变量","B. 动态变量","C. 局部变量","D. 声明变量"],"ans":0,"explain":"静态变量是唯一为类中所有对象共享的变量。"},{"id":"java13215-pl-P4085834","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在Java中，调用静态方法时，应该使用什么作为前缀？（）","opts":["A. 对象实例名","B. 类名","C. 方法名","D. 关键字static"],"ans":1,"explain":"调用静态方法时，前缀使用的是类名，而不是对象实例名。"},{"id":"java13215-pl-P4085835","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Java使用基本数据类型、类和（ ）来表示数据。","opts":["A. 变量","B. 对象","C. 常量","D. 属性"],"ans":1,"explain":"Java使用基本数据类型（如int、double、char和boolean）、类和对象来表示数据。"},{"id":"java13215-pl-P4085836","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"包装类的构造方法接受（）个基本数据类型的值，并保存它。","opts":["A. 1","B. 2","C. 3","D. 4"],"ans":0,"explain":"包装类的构造方法接受一个基本数据类型的值，并保存它。"},{"id":"java13215-pl-P4085837","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"调用静态方法时不依赖于任何的（）。","opts":["A. 实例变量","B. 实例对象","C. 实例常量","D. 实例属性"],"ans":1,"explain":"调用静态方法时不依赖于任何的实例对象。"},{"id":"java13215-pl-P4085838","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"数组的初始化分为（）。","opts":["A. 静态初始化和动态初始化","B. 手动初始化和自动初始化","C. 显式初始化和隐式初始化","D. 一次性初始化和多次初始化"],"ans":0,"explain":"数组的初始化分为静态初始化和动态初始化两种。"},{"id":"java13215-pl-P4085839","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"在Java中，对于多维数组的内存分配，以下哪个说法是正确的？（）","opts":["A. 可以从任意一维开始分配内存。","B. 必须从最低维开始分配内存。","C. 必须从最高维开始分配内存。","D. 分配内存的顺序与维数无关。"],"ans":2,"explain":"按维分配是从最高维起（而且必须从最高维开始），分别为每一维分配内存。"},{"id":"java13215-pl-P4085840","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"在二维数组中，哪一维通常被称为行，而哪一维被称为列？（）","opts":["A. 第一维是行，第二维是列","B. 第一维是列，第二维是行","C. 两者都可以随意交换称呼","D. 二维数组中不存在行和列的概念"],"ans":0,"explain":"在二维数组中，第一维也称为行，第二维也称为列。"},{"id":"java13215-pl-P4085841","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"在Java的System类中，哪个方法用于实现数组之间的复制？（）","opts":["A. arraycopy()","B. copyArray()","C. arrayclone()","D. arrayduplicate()"],"ans":0,"explain":"System类中提供了一个特殊的方法arraycopy（），它可以实现数组之间的复制。"},{"id":"java13215-pl-P4085842","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"字符串是由有限个字符组成的序列，Java中的字符串是一个（）。","opts":["A. 对象","B. 属性","C. 基本类型","D. 以‘\\0’结尾的字符数组"],"ans":0,"explain":"字符串是由有限个字符组成的序列，Java中的字符串是一个对象，而不是一个以“\\0”结尾的字符数组。"},{"id":"java13215-pl-P4085843","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"在处理需要频繁修改和包含大量操作的字符串时，应该使用哪个类？（）","opts":["A. StringSequence","B. StringBuilder","C. StringBuffer","D. CharSequence"],"ans":2,"explain":"对于那些需要改变内容并有许多操作的字符串，可以使用StringBuffer类。"},{"id":"java13215-pl-P4085844","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"在Java程序中，字符串可以被分类为哪两种类型？（）","opts":["A. 常量和变量","B. 值和引用","C. 静态和动态","D. 原始和封装"],"ans":0,"explain":"Java程序中的字符串分为常量和变量两种，其中字符串常量是用双引号括起来的一串字符。"},{"id":"java13215-pl-P4085845","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"String类型字符串的连接还可以使用运算符“（）”来实现。","opts":["A. +","B. -","C. *","D. /"],"ans":0,"explain":"String类型字符串的连接还可以使用运算符“+”来实现。"},{"id":"java13215-pl-P4085846","type":"sc","tier":"基础","conf":"adapt","chap":"第5章","q":"Vector是（）提供的一个非常重要的工具类。","opts":["A. java.lang包","B. java.io包","C. java.awt包","D. java.util包"],"ans":3,"explain":"Vector是java.util包提供的一个非常重要的工具类，它类似于数组，可以使用整数下标来访问各个元素，但是比数组的功能更强大。"},{"id":"java13215-pl-P4086054","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：标记了static关键字的方法称为（），或称类方法。","opts":[],"ans":null,"explain":"标记了static关键字的方法称为静态方法，或称类方法。\n静态方法"},{"id":"java13215-pl-P4086055","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述使用静态方法时，必须注意的两个特别限制。","opts":[],"ans":null,"explain":"（1）由于静态方法可以在没有定义它所从属的类的对象的情况下加以调用，故不存在this值。因此，一个静态方法只能使用参数及内部定义的局部变量和类中定义的静态变量，如果使用非静态变量将引起编译错误。<br/>（2）静态方法不能被重写。也就是说，在这个类的后代类中，不能有相同名称、相同参数列表的方法。"},{"id":"java13215-pl-P4086056","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：所有的包装类都定义在（）包中。","opts":[],"ans":null,"explain":"所有的包装类都定义在java.lang包中。\njava.lang"},{"id":"java13215-pl-P4086057","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"填空题：自动将基本数据类型转为对应的包装类的过程称为（）。","opts":[],"ans":null,"explain":"自动将基本数据类型转为对应的包装类的过程称为自动装箱（Autoboxing）。\n自动装箱（或Autoboxing）"},{"id":"java13215-pl-P4086058","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述什么是自动装箱、自动拆箱？","opts":[],"ans":null,"explain":"自动将基本数据类型转为对应的包装类的过程称为自动装箱。自动将包装类转为对应的基本数据类型过程称为自动拆箱。"},{"id":"java13215-pl-P4086059","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：数组中各元素的类型相同，可以通过下标来访问数组中的元素，下标从（）开始。","opts":[],"ans":null,"explain":"数组中各元素的类型相同，可以通过下标来访问数组中的元素，下标从0开始。\n0（或零）"},{"id":"java13215-pl-P4086060","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：在定义数组时并不会为数组分配内存，因此方括号[]中不需要指出数组元素的个数，即（）。","opts":[],"ans":null,"explain":"在定义数组时并不会为数组分配内存，因此方括号[]中不需要指出数组元素的个数，即数组长度。\n数组长度"},{"id":"java13215-pl-P4086061","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：静态初始化使用一对（）将初值括起来，每个元素对应一个引用。","opts":[],"ans":null,"explain":"静态初始化使用一对大括号将初值括起来，每个元素对应一个引用。\n大括号（或“{}”）"},{"id":"java13215-pl-P4086062","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：在Java中，数组下标从0开始，数组中的元素个数（）是数组类中唯一的数据成员变量。","opts":[],"ans":null,"explain":"在Java中，数组下标从0开始，数组中的元素个数length是数组类中唯一的数据成员变量。\nlength"},{"id":"java13215-pl-P4086063","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：对二维数组进行动态初始化时，有两种分配内存空间的方法：直接分配与（）。","opts":[],"ans":null,"explain":"对二维数组进行动态初始化时，有两种分配内存空间的方法：直接分配与按维分配。\n按维分配"},{"id":"java13215-pl-P4086064","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：数组下标也称为（）。","opts":[],"ans":null,"explain":"数组下标也称为索引，它们都可以是整型常数和表达式，都是从0开始的。\n索引"},{"id":"java13215-pl-P4086065","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：数组下标也称为索引，它们都可以是整型常数和（），都是从0开始的。","opts":[],"ans":null,"explain":"数组下标也称为索引，它们都可以是整型常数和表达式，都是从0开始的。\n表达式"},{"id":"java13215-pl-P4086066","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述java.util.Arrays中为数组提供的静态方法。","opts":[],"ans":null,"explain":"（1）equals（type[　]，type[　]）<br/>equals（type[　]，type[　]）可用来判定type类型的两个数组的值是否相同，type可以是基本数据类型，也可以是类类型。如果两个指定的数组彼此相等，则返回true。如果数组元素为对象，那么将调用对象的equals（）方法来判断是否相同。<br/>（2）sort（type[　]）<br/>sort（type[　]）将type类型的数组按照升序排序，如果数组元素为对象，那么将调用对象的compareTo（）来得到比较结果。<br/>（3）fill（type[　]，typevalue）<br/>fill（type[　]，typevalue）将type类型的值value赋给type类型数组的每个元素。<br/>（4）binarySearch（type[　]，typevalue）<br/>binarySearch（type[　]，typevalue）采用二分查找法在type类型的数组中查找type类型的值value。"},{"id":"java13215-pl-P4086067","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：对（）类的实例进行查找、比较、连接等操作时，既不能输入新字符，也不能改变字符串的长度。","opts":[],"ans":null,"explain":"对String类的实例进行查找、比较、连接等操作时，既不能输入新字符，也不能改变字符串的长度。\nString"},{"id":"java13215-pl-P4086068","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：Java程序中的字符串分为常量和变量两种，其中字符串常量是用（）括起来的一串字符。","opts":[],"ans":null,"explain":"Java程序中的字符串分为常量和变量两种，其中字符串常量是用双引号括起来的一串字符。\n双引号（或“”）"},{"id":"java13215-pl-P4086069","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述String类和StringBuffer类中共有的常用方法。","opts":[],"ans":null,"explain":"String类和StringBuffer类中共有的常用方法如下：<br/>（1）length（）：返回字符串的长度，即字符个数。<br/>（2）charAt（int　index）：返回字符串中index位置的字符。<br/>（3）subString（int　beginlndex）：截取当前字符串中从beginIndex开始到末尾的子串。<br/>String类中的常用方法如下。<br/>（1）replace（char　oldChar，char　newChar）：将当前字符串中出现的所有oldChar转换为newChar。<br/>（2）toLowerCase（）：将当前字符串中所有字符转换为小写形式。<br/>（3）toUpperCase（）：将当前字符串中所有字符转换为大写形式。<br/>（4）concat（String　str）：将str连接在当前字符串的尾部。<br/>（5）startsWith（String　prefix）：测试prefix是否是当前字符串的前缀。<br/>（6）trim（）：去掉字符串前面及后面的空白。<br/>（7）valueOf（type　value）：将type类型的参数value转为字符串形式。"},{"id":"java13215-pl-P4086070","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述StringBuffer类中的常用方法。","opts":[],"ans":null,"explain":"StringBuffer类中的常用方法如下。<br/>（1）append（String　str）：将参数str表示的字符串添加到当前串的最后。<br/>（2）replace（int　start，int　end，String　str）：使用给定的str替换从start到end之间的子串。<br/>（3）capacity（）：返回当前的容量。"},{"id":"java13215-pl-P4086071","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：对于StringBuffer类对象，length（）方法获得的是字符串的长度，capacity（）方法返回当前的（），即字符串长度再加上缓冲区的大小。","opts":[],"ans":null,"explain":"对于StringBuffer类对象，length（）方法获得的是字符串的长度，capacity（）方法返回当前的容量，即字符串长度再加上缓冲区的大小。\n容量"},{"id":"java13215-pl-P4086072","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述Vector类包含的3个成员变量。","opts":[],"ans":null,"explain":"（1）protected　int　capacityIncrement：增量的大小。如果值为0，则缓冲区的大小每次倍增。<br/>（2）protected　int　elementCount：Vector对象中元素的数量。<br/>（3）protected　Object　elementData[　]：元素存储的数组缓冲区。"},{"id":"java13215-pl-P4086073","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述常用的Vector类的3个构造方法。","opts":[],"ans":null,"explain":"常用的Vector类的3个构造方法如下：<br/>（1）publicVector（）：构造一个空向量。<br/>（2）public　Vector（int　initialCapacity）：以指定的初始存储容量initialCapacity构造一个空的向量Vector<br/>（3）public　Vector（int　initialCapacity，int　capacityIncrement）：以指定的初始存储容量initialCapacity和容量增量capacityIncrement构造一个空的向量Vector。"},{"id":"java13215-pl-P4086074","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"简述向Vector类对象中添加元素的常用方法。","opts":[],"ans":null,"explain":"向Vector类对象中添加元素的常用方法如下：<br/>（1）addElement（E　obj）：将指定的组件obj添加到本向量的末尾，长度加1。<br/>（2）insertElementAt（E　obj，int　index）：将指定对象obj作为组件插入到本向量指定位置index处。<br/>（3）add（int　index，E　obj）：在本向量的指定位置index插入指定的元素obj。"},{"id":"java13215-pl-P4086075","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"程序填空题：先创建一个Vector,再删除掉其中的所有字符串对象“to”。 Vector&lt;String&gt; MyVecto = new Vector&lt;String&gt;(100); for (int i=0; ① ;i++){ MyVector.addElement(&quot;welcome&quot;); MyVector.addElement(&quot;to&quot;); MyVector.addElement(&quot;beijing&quot;); } while (MyVector. ② );","opts":[],"ans":null,"explain":"①i&lt;10<br/>②removeElement(&quot;to&quot;)"},{"id":"java13215-pl-P4086076","type":"sa","tier":"创新","conf":"adapt","chap":"第5章","q":"填空题：使用Vector时，一定要先创建后使用。如果不先使用new运算符利用构造函数创建Vector类的对象，而直接使用Vector的方法（如addElement（）等方法），则可能造成堆栈溢出或使用（）指针异常等。","opts":[],"ans":null,"explain":"使用Vector时，一定要先创建后使用。如果不先使用new运算符利用构造函数创建Vector类的对象，而直接使用Vector的方法，则可能造成堆栈溢出或使用null指针异常等。\nnull"},{"id":"java13215-pl-P4085966","type":"sa","tier":"拔高","conf":"adapt","chap":"第4章","q":"程序分析题：编译运行下面的程序，结果是什么？ class Dog{ String dogname; int age; Dog(){ } Dog(String name){dogname= name;} } void bark (int count){ System.out.printIn(dogname+&quot;bark:&quot;+this.age); } void bark(){ return; } double bark (int ab){ return 4.14; } } public class DogTest3{ void bark(){ return; } public static void main(String[] args){ Dog g1; } }","opts":[],"ans":null,"explain":"至少第6行和第12行定义的bark方法冲突，出现编译错误"},{"id":"java13215-pl-P4085968","type":"sa","tier":"拔高","conf":"adapt","chap":"第5章","q":"程序分析题：阅读以下程序，请写出该程序的输出结果。 public class Test1{ static void s(int[]b,int k){ int i,j,t; for(i=1;i&lt;k;i++){ for(t=b[i],j=i-1;j&gt;=0 &amp;&amp; t&gt;b[j];j--) b[j+1]=b[j]; b[j+1]=t; } } public static void main(String[] args){ int i;int[] a={16,12,27,11,13,33}; s(a,6); for(i=0;i&lt;a.length;i++)System.out.print(a[i]+&quot; &quot;); System.out.println(); } }","opts":[],"ans":null,"explain":"33　　27　　　16　　　13　　　12　　　11"},{"id":"java13215-pl-P4085969","type":"sa","tier":"拔高","conf":"adapt","chap":"第5章","q":"程序分析题：阅读以下程序，请写出该方法的功能。 static int[] fun(int[] a){ for(int i=0;i&lt;a.length-1;i++){ for(int j=i+1;j&lt;a.length;j++){ if (a[i]&gt;a[j]){ int temp=a[i];a[i]=a[j];a[j]=temp; } } } return a; }","opts":[],"ans":null,"explain":"该方法对输入的一维数组中各元素按照从小到大顺序进行排列，并返回排序后的数组。"},{"id":"java13215-pl-P4085967","type":"calc","tier":"创新","conf":"adapt","chap":"第5章","q":"程序设计题：请编写方法int lessKeyFirst(int[] a,int key),该方法的功能是返回已知整数数组a内第一个小于指定值key的元素的下标。若没有找到小于key的元素，则返回-1。 int lessKeyFirst(int[] a,int key){ //请在此处填写应编写的代码 }","opts":[],"ans":null,"explain":"for(int　i=0;i&lt;a.length;i++){<br/>　if(a[i]&lt;key)<br/>　return　i;<br/>　}<br/>　return　-1;"},{"id":"java13215-pl-P4085970","type":"calc","tier":"创新","conf":"adapt","chap":"第5章","q":"程序设计题：计算myTable中各行元素之和并查找其和值最大的那一行。 public class TableTester{ public static void main(String args[]){ int myTable[][]={{23,45,65,34,21,67,78}, {46,14,18,46,98,63,88}, {98,81,64,90,21,14,23}, {54,43,55,76,22,43,33}}; int sum,max,maxRow = Integer.MIN_VALUE; max = Integer.MIN_VALUE; //请在此处填写应编写的代码 System.out.println(&quot;Row &quot; + maxRow + &quot; has the MAX sum of &quot; + max); } }","opts":[],"ans":null,"explain":"for(int　row=0;row&lt;4;row++){<br/>　　　　　　　　　sum=0;<br/>　　　　　　　　　for(int　col　=　0;col　&lt;7;col++)<br/>　　　　　　　　　　　　　　　　　　sum+　=　myTable[row][col];<br/>　　　　　　　　　　　　　if　(sum&gt;max){<br/>　　　　　　　　　　　　　　　　　　　　　　max　=　sum;<br/>　　　　　　　　　　　　　　　　　　　　　　maxRow　=　　row;<br/>　　　　　　　　　　　　　}　　　　　<br/>}"},{"id":"java13215-pl-P4085847","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，哪个关键字用于表示一个类是从另一个类派生或继承的？（）","opts":["A. implements","B. extends","C. inherits","D. derivatives"],"ans":1,"explain":"在Java中，用关键字extends表示派生。"},{"id":"java13215-pl-P4085848","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，Object类扮演了什么样的角色？（）","opts":["A. Object类是所有类的子类。","B. Object类是所有类的父类或祖先类。","C. Object类是所有接口的父类或祖先类。","D. Object类只是java.lang包中的一个普通类。"],"ans":1,"explain":"Java中预定义及程序员自己定义的任何类都直接或间接地派生于Object类，Object类是所有类的父类或祖先类。"},{"id":"java13215-pl-P4085849","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"（）类是Java程序中所有类的直接或间接父类，处在类层次的最高点。","opts":["A. extends","B. Object","C. Class","D. Manager"],"ans":1,"explain":"Object类是Java程序中所有类的直接或间接父类，处在类层次的最高点，所有其他的类都是从Object类派生而来的。"},{"id":"java13215-pl-P4085850","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，要判断两个对象是否相等，可以使用哪两种方式？（）","opts":["A. == 运算符和 equals() 方法","B. equals() 方法和 hashCode() 方法","C. == 运算符和 clone() 方法","D. == 运算符和 toString() 方法"],"ans":0,"explain":"关于对象相等的判别，在Java中有两种方式。一种是使用= =运算符，另一种是使用equals（）方法。"},{"id":"java13215-pl-P4085851","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"Java是完全的（）语言，具有完全的OOP能力。","opts":["A. 面向过程","B. 命令式编程","C. 函数式编程","D. 面向对象"],"ans":3,"explain":"Java是完全的面向对象语言，具有完全的OOP能力。"},{"id":"java13215-pl-P4085852","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"Java中的类继承机制采用了哪种方式？（）","opts":["A. 接口继承","B. 多重继承","C. 单重继承","D. 原型继承"],"ans":2,"explain":"在类的继承机制中，Java抛弃了多重继承功能，仅实现了单重继承机制。"},{"id":"java13215-pl-P4085853","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"（）是指从多个类共同派生一个子类，即一个类可以有多个父。","opts":["A. 接口继承","B. 多重继承","C. 单重继承","D. 原型继承"],"ans":1,"explain":"多重继承是指从多个类共同派生一个子类，即一个类可以有多个父。"},{"id":"java13215-pl-P4085854","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，子类可以继承父类的哪些元素？（）","opts":["A. 所有方法和成员变量","B. 所有方法和成员变量，包括构造方法","C. 所有方法、成员变量和内部类","D. 所有方法和成员变量，但不包括构造方法"],"ans":3,"explain":"虽然一个子类可以从父类及祖先类中继承所有能继承的方法和成员变量，但它不能继承构造方法。"},{"id":"java13215-pl-P4085855","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，一个类获得构造方法的途径有哪些？（）","opts":["A. 只有系统默认提供一个构造方法","B. 只能通过编写多个构造方法来创建对象","C. 可以通过自己编写构造方法，或者在用户没有编写构造方法的时候，由系统为类提供唯一一个默认的构造方法","D. 只能通过继承父类的构造方法来获得"],"ans":2,"explain":"只有两种方式能让一个类得到构造方法，一种方式是自己编写构造方法；另一种方式是，在用户没有编写构造方法的时候，由系统为类提供唯一一个默认的构造方法。"},{"id":"java13215-pl-P4085856","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，子类对于父类的私有成员（属性和方法）有何访问权限？（）","opts":["A. 子类可以直接访问父类的私有属性和方法。","B. 子类无法访问父类的私有属性和方法。","C. 子类只能访问父类的公有属性和方法。","D. 子类可以使用父类中定义的公有（及保护）方法访问私有数据成员。"],"ans":3,"explain":"子类不能直接访问其父类中定义的私有属性及方法，但可以使用父类中定义的公有（及保护）方法访问私有数据成员。"},{"id":"java13215-pl-P4085857","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，将一个子类的对象赋值给一个父类类型的变量，这个过程称为（）。","opts":["A. 继承","B. 多态","C. 对象转型","D. 封装"],"ans":2,"explain":"和大多数面向对象的语言一样，Java允许使用对象的父类类型的一个变量指示该对象，比如对于前面定义的Employee类和Manager类，可以将子类的对象赋给父类的变量，这称为对象转型（Casting）。"},{"id":"java13215-pl-P4085858","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"当子类（）父类方法时，子类与父类使用的是相同的方法名及参数列表，但可以执行不同的功能，当然子类中也可以什么都不做。","opts":["A. 重写","B. 继承","C. 重载","D. 替换"],"ans":0,"explain":"当子类重写父类方法时，子类与父类使用的是相同的方法名及参数列表，但可以执行不同的功能，当然子类中也可以什么都不做。"},{"id":"java13215-pl-P4085859","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，当子类覆盖父类中的同名方法时，子类方法的访问权限应该是怎样的？（）","opts":["A. 子类方法可以比父类方法更严格的访问权限。","B. 子类方法不可以比父类方法更宽松的访问权限。","C. 子类方法的访问权限必须与父类方法完全相同。","D. 子类方法不能比父类方法更严格的访问权限。"],"ans":3,"explain":"要注意的是，覆盖的同名方法中，子类方法不能比父类方法的访问权限更严格。"},{"id":"java13215-pl-P4085860","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"如果方法名相同，而参数列表不同，则是对方法的（）。","opts":["A. 重写","B. 继承","C. 重载","D. 替换"],"ans":2,"explain":"注意，如果方法名相同，而参数列表不同，则是对方法的重载。"},{"id":"java13215-pl-P4085861","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"如果子类已经重写了父类中的方法，但在子类中还想使用父类中被隐藏的方法，可以使用（）关键字。","opts":["A. extends","B. super","C. public","D. Person"],"ans":1,"explain":"如果子类已经重写了父类中的方法，但在子类中还想使用父类中被隐藏的方法，可以使用super关键字。"},{"id":"java13215-pl-P4085862","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，关于方法重载和方法覆盖，以下哪种说法是正确的？（）","opts":["A. 重载的方法和覆盖的方法都必须在同一个类中。","B. 重载的方法和覆盖的方法可以分属于不同的类。","C. 重载的方法属于同一个类，覆盖的方法则分属于父类、子类中。","D. 重载的方法和覆盖的方法都不能分属于父类、子类中。"],"ans":2,"explain":"重载的方法属于同一个类，覆盖的方法则分属于父类、子类中。"},{"id":"java13215-pl-P4085863","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"如果在子类构造方法的定义中调用了父类的构造方法，则调用语句必须出现在子类构造方法的（）。","opts":["A. 第一行","B. 第二行","C. 下一行","D. 最后一行"],"ans":0,"explain":"如果在子类构造方法的定义中调用了父类的构造方法，则调用语句必须出现在子类构造方法的第一行。"},{"id":"java13215-pl-P4085864","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，使用super()来调用父类构造方法时，以下哪个说法是正确的？（）","opts":["A. super()的参数个数必须和父类构造方法的参数个数完全相同。","B. super()的参数个数没有限制，只要其参数列表和父类中的某个构造方法的参数列表相符即可。","C. super()只能调用父类的无参数构造方法。","D. super()不能用于调用父类的构造方法。"],"ans":1,"explain":"一般来讲，调用super（）时，参数的个数没有限制，只要其参数列表和父类中的某个构造方法的参数列表相符即可。"},{"id":"java13215-pl-P4085865","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，通常情况下，无参数的默认构造方法的作用是什么？（）","opts":["A. 用于创建子类的对象。","B. 用于初始化父类对象。","C. 用于释放系统资源。","D. 用于调用其他类的构造方法。"],"ans":1,"explain":"在通常情况下，没有参数的默认构造方法常被用来初始化父类对象。"},{"id":"java13215-pl-P4085866","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，如果要在子类的构造方法中显式调用父类的构造方法，super()的调用应该放在什么位置？（）","opts":["A. 在子类构造方法的中间位置。","B. 在子类构造方法的末尾位置。","C. 在子类构造方法的开头位置。","D. 在子类构造方法的任何位置都可以。"],"ans":2,"explain":"如果要显式调用父类的构造方法，super（）调用必须放在子类构造方法的开头位置。"},{"id":"java13215-pl-P4085867","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在编程中，关于变量的静态类型，以下哪个描述是正确的？（）","opts":["A. 变量的静态类型是程序运行期间赋予变量的实际类型。","B. 变量的静态类型在变量被赋值时确定。","C. 变量的静态类型是出现在变量声明中的类型。","D. 变量的静态类型在程序执行过程中可以改变。"],"ans":2,"explain":"变量的静态类型是出现在声明中的类型。"},{"id":"java13215-pl-P4085868","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"运行过程中某一时刻变量指向的对象的类型称为（）。","opts":["A. 静态类型","B. 动态类型","C. 引用类型","D. 声明类型"],"ans":1,"explain":"运行过程中某一时刻变量指向的对象的类型称为动态类型，这是它此刻的真正类型。"},{"id":"java13215-pl-P4085869","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"调用稍后可能被覆盖的方法的这种处理方式称为（）。","opts":["A. 静态绑定","B. 动态绑定","C. 过载绑定","D. 强制绑定"],"ans":1,"explain":"调用稍后可能被覆盖的方法的这种处理方式，称为动态绑定或后绑定。动态绑定一定要到运行时才能确定要执行的方法代码。"},{"id":"java13215-pl-P4085870","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在编译过程中能确定调用方法的处理方式称为（）。","opts":["A. 静态绑定","B. 动态绑定","C. 过载绑定","D. 强制绑定"],"ans":0,"explain":"在编译过程中能确定调用方法的处理方式，称为静态绑定或前绑定。"},{"id":"java13215-pl-P4085871","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"Java中有一个重要的关键字（），它表示终极，既可以修饰一个类，也可以修饰类中的成员变量或成员方法。","opts":["A. class","B. final","C. static","D. void"],"ans":1,"explain":"Java中有一个重要的关键字final，它表示终极，既可以修饰一个类，也可以修饰类中的成员变量或成员方法。"},{"id":"java13215-pl-P4085872","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"使用（）修饰的方法的方法体为空，修饰的类必须被子类继承。","opts":["A. final","B. native","C. abstract","D. public"],"ans":2,"explain":"使用abstract修饰的方法的方法体为空，修饰的类必须被子类继承。"},{"id":"java13215-pl-P4085873","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，关于java.lang.String类，下列描述正确的是（）。","opts":["A. String类不是final类故可以继承","B. String类不是final类故不可继承","C. String类是final类故不可继承","D. String类final类故可以继承"],"ans":2,"explain":"String类是final类。有的时候一些类是不能被继承的，Java中预定义的类Java.lang.String就是如此。"},{"id":"java13215-pl-P4085874","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在Java中，如果一个方法被标记为final，那么这个方法具有什么特性？（）","opts":["A. 它可以在子类中被覆盖。","B. 它的访问修饰符必须是public。","C. 它的实现不能被覆盖，从而确保总是调用最原始的方法。","D. 它的返回值类型必须与父类中的方法相同。"],"ans":2,"explain":"被标记final的方法将不能被覆盖，从而可以确保被调用的方法是最原始的方法，而不是已被更改的子类中的方法。"},{"id":"java13215-pl-P4085875","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在编程中，一个被标记为final的变量通常被称为（）。","opts":["A. 静态变量","B. 动态变量","C. 随机变量","D. 终极变量"],"ans":3,"explain":"一个变量被标记为final，称为终极变量或终态变量，实际上它会成为一个常量，企图改变终极变量的值将引起编译错误。"},{"id":"java13215-pl-P4085876","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"像Drawing类这种定义了方法但没有定义具体实现的类称为（）。","opts":["A. 抽象类","B. 终极类","C. 匿名类","D. 内部类"],"ans":0,"explain":"像Drawing类这种定义了方法但没有定义具体实现的类称为抽象类。"},{"id":"java13215-pl-P4085877","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在面向对象编程中，以下关于抽象类的说法哪一个是正确的？（）","opts":["A. 可以直接使用抽象类创建对象实例。","B. 抽象类不能直接实例化，但可以通过子类间接实例化。","C. 抽象类不能被继承。","D. 抽象类只能有一个子类。"],"ans":1,"explain":"在程序中不能用抽象类作为模板来创建对象，必须生成抽象类的一个非抽象的子类后才能创建实例。抽象类是不能创建对象的，除非通过间接的方法来创建其子类的对象，但是可以定义一个抽象类的引用变量。"},{"id":"java13215-pl-P4085878","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"如果一个抽象类除了抽象方法外什么都没有，则使用（）更为合适。","opts":["A. 继承","B. 构造方法","C. 终极类","D. 接口"],"ans":3,"explain":"如果一个抽象类除了抽象方法外什么都没有，则使用接口更为合适。"},{"id":"java13215-pl-P4085879","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"要实现接口，可以在类的声明中用关键字（）来表示。","opts":["A. implements","B. extends","C. inherits","D. derivatives"],"ans":0,"explain":"要实现接口，可以在类的声明中用关键字implements来表示。"},{"id":"java13215-pl-P4085880","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"下面关于Java接口的说法正确的是（）。","opts":["A. Java接口中定义的不是扩展功能","B. Java接口中可以被多个子类实现，一个类也可以同时实现多个接口","C. Java接口中可以声明私有成员","D. Java接口可以被实例化"],"ans":1,"explain":"Java程序中，可以在implements后面声明多个接口名，也就是一个类可以实现多个接口。 Java接口中定义的是扩展功能。 Java接口不能被实例化。 Java接口中不可以声明私有成员。"},{"id":"java13215-pl-P4085881","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"接口实际上就是一个特殊的抽象类，同时实现多个接口就意味着具有（）的能力。","opts":["A. 接口继承","B. 多重继承","C. 单重继承","D. 原型继承"],"ans":1,"explain":"接口实际上就是一个特殊的抽象类，同时实现多个接口就意味着具有多重继承的能力。"},{"id":"java13215-pl-P4085882","type":"sc","tier":"基础","conf":"adapt","chap":"第6章","q":"在接口的定义中，Java允许省略定义数据成员的final关键字、方法的public及（）关键字。","opts":["A. interface","B. virtual","C. method","D. abstract"],"ans":3,"explain":"在接口的定义中，Java允许省略定义数据成员的final关键字、方法的public及abstract关键字。"},{"id":"java13215-pl-P4085883","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在Java中，把这些不同类型的输入、输出源抽象为流，其中输入或输出的数据称为（），用统一的接口来表示。","opts":["A. 对象流","B. 数据流","C. 字符流","D. 字节流"],"ans":1,"explain":"在Java中，把这些不同类型的输入、输出源抽象为流（Stream），其中输入或输出的数据称为数据流（DataStream），用统一的接口来表示。"},{"id":"java13215-pl-P4085884","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"以下哪个描述最准确地反映了数据流的定义？（）","opts":["A. 数据流是一组无序的字节集合。","B. 数据流中的字节可以没有起点或终点。","C. 数据流是由一组有顺序的、有起点和终点的字节集合组成的。","D. 数据流不包含起点和终点。"],"ans":2,"explain":"数据流是指一组有顺序的、有起点和终点的字节集合。"},{"id":"java13215-pl-P4085885","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"数据流分为输入数据流和输出数据流。输出数据流（）。","opts":["A. 只能写不能读","B. 只能读不能写","C. 能读能写","D. 不能读也不能写"],"ans":0,"explain":"数据流分为输入数据流和输出数据流，输入数据流只能读不能写，而输出数据流只能写不能读。"},{"id":"java13215-pl-P4085886","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在Java的java.io包中，以下哪个类不属于表示数据流的四个基本抽象类之一？（）","opts":["A. InputStream","B. OutputStream","C. Reader","D. File"],"ans":3,"explain":"java.io包中提供了表示数据流的4个基本抽象类，分别是InputStream、OutputStream、Reader和Writer。"},{"id":"java13215-pl-P4085887","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"对数据流中字节的读取通常是从头到尾顺序进行的，如果需要以反方向读取，则使用（）。","opts":["A. 顺序读取","B. 跳过读取","C. 回推操作","D. 随机访问"],"ans":2,"explain":"对数据流中字节的读取通常是从头到尾顺序进行的，如果需要以反方向读取，则使用回推（Push Back）操作。"},{"id":"java13215-pl-P4085888","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"文件数据流包括（）。","opts":["A. InputStreamReader和OutputStreamWriter","B. FileReader和FileWriter","C. FileInputStream和FileOutputStream","D. RandomAccessFile和BufferedOutputStream"],"ans":2,"explain":"文件数据流包括FileInputStream和FileOutputStream，这两个类用来进行文件的I/O处理，其数据源或数据终点都应当是文件。"},{"id":"java13215-pl-P4085889","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在Java中，BufferedInputStream和BufferedOutputStream属于哪种类型的数据流？（）","opts":["A. 抽象数据流","B. 缓冲区数据流","C. 文件数据流","D. 网络数据流"],"ans":1,"explain":"缓冲区数据流有BufferedInputStream和BufferedOutputStream，它们是在数据流上增加了一个缓冲区，都属于过滤器数据流。"},{"id":"java13215-pl-P4085890","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"一般在关闭一个缓冲区输出流之前，应先使用（）方法，强制输出剩余数据，以确保缓冲区内的所有数据全部写入输出流。","opts":["A. mark（）","B. skip（）","C. reset（）","D. flush（）"],"ans":3,"explain":"一般在关闭一个缓冲区输出流之前，应先使用flush（）方法，强制输出剩余数据，以确保缓冲区内的所有数据全部写入输出流。"},{"id":"java13215-pl-P4085891","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在Java中，要实现对对象进行文件I/O操作，即把对象写入文件数据流或从文件数据流中读出，通常使用的两个类是？（）","opts":["A. FileInputStream和FileOutputStream","B. InputStreamReader和OutputStreamWriter","C. ObjectInputStream和ObjectOutputStream","D. FileReader和FileWriter"],"ans":2,"explain":"Java中的数据流不仅能对基本数据类型的数据进行操作，还提供了把对象写入文件数据流或从文件数据流中读出的功能，这一功能是通过java.io包中ObjectInputStream和ObjectOutputStream两个类实现的。"},{"id":"java13215-pl-P4085892","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"能够输入/输出对象的流称为（）。","opts":["A. 对象流","B. 数据流","C. 字符流","D. 字节流"],"ans":0,"explain":"能够输入/输出对象的流称为对象流。"},{"id":"java13215-pl-P4085893","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"能够记录自己的状态以便将来得到复原的能力，称为对象的（）。","opts":["A. 唯一性","B. 依赖性","C. 继承性","D. 持久性"],"ans":3,"explain":"能够记录自己的状态以便将来得到复原的能力，称为对象的持久性（Persistence）。"},{"id":"java13215-pl-P4085894","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"下列关于序列化描述不正确的是（ ）。","opts":["A. 序列化不能保存对象的非静态成员变量","B. 序列化不能保存任何成员方法和静态成员变量","C. 序列化保存的只是变量的值，对于变量的任何修饰符都不能保存","D. 访问权限（pubpc，protected，private)对于数据域的序列化没有影响"],"ans":0,"explain":"序列化只能保存对象的非静态成员变量，而不能保存任何成员方法和静态成员变量，并且保存的只是变量的值，不能保存变量的任何修饰符，访问权限（如public、protected、private）对于数据域的序列化没有影响。"},{"id":"java13215-pl-P4085895","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"任何用（）关键字标明的成员变量，都不会被保存。","opts":["A. public","B. transient","C. thread","D. trans"],"ans":1,"explain":"任何用transient关键字标明的成员变量，都不会被保存。"},{"id":"java13215-pl-P4086077","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：子类与父类的关系是：子类对象“is a”或（）父类对象，也就是说，子类中的任何一个成员也是父类中的一个成员。","opts":[],"ans":null,"explain":"子类与父类的关系是：子类对象“is a”（或“is a kind of”）父类对象，也就是说，子类中的任何一个成员也是父类中的一个成员。\n“is　a　kind　of”"},{"id":"java13215-pl-P4086078","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：汽车包括了车身与发动机，但不能说它们之间存在“is a”关系，它们只是整体与部分的关系，一般称为（）关系。","opts":[],"ans":null,"explain":"汽车包括了车身与发动机，但不能说它们之间存在“is a”关系，它们只是整体与部分的关系，一般称为“has a”关系。\n“has　a”"},{"id":"java13215-pl-P4086079","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：如果一个类的定义中没有出现extends关键字，则表明这个类派生于（）类。","opts":[],"ans":null,"explain":"如果一个类的定义中没有出现extends关键字，则表明这个类派生于Object类。\nObject"},{"id":"java13215-pl-P4086080","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"程序填空题：编译运行下面的程序。 public class A{ public static void main(String[] args)( B b = new B(); b.test(); } void test(){ System.out.print(&quot;A&quot;); } } class B ① A{ void test(){ super. ② ; System.out.print(&quot;B&quot;); } }","opts":[],"ans":null,"explain":"①extends<br/>②test()"},{"id":"java13215-pl-P4086081","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：在程序中，有时需要判明一个引用到底指向哪个实例，这可以通过（）运算符来实现。","opts":[],"ans":null,"explain":"在程序中，有时需要判明一个引用到底指向哪个实例，这可以通过instanceof运算符来实现。\ninstanceof"},{"id":"java13215-pl-P4086082","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：如果父类中方法method（）的访问权限是public，则子类中就不能含有（）的method（），否则会出现编译错误。","opts":[],"ans":null,"explain":"如果父类中方法method（）的访问权限是public，则子类中就不能含有private的method（），否则会出现编译错误。\nprivate"},{"id":"java13215-pl-P4086083","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"简述应用覆盖时必须注意的两条重要规则。","opts":[],"ans":null,"explain":"（1）覆盖方法的允许访问范围不能低于原方法。<br/>（2）覆盖方法所抛出的异常不能比原方法更多。"},{"id":"java13215-pl-P4086084","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"简述使用super时，要注意的两个问题。","opts":[],"ans":null,"explain":"首先，使用super.method（）调用父类中的方法method（），将执行父类方法中的所有操作，其中可能会包括一些原本不希望进行的操作，所以调用时要谨慎。<br/>其次，由继承性的机制可以知道，super.method（）语句所调用的这个方法不一定是在父类中加以描述的，它也可能是父类从它的祖先类中继承而来的，因此，有可能需要按继承层次关系依次向上查询才能够找得到。"},{"id":"java13215-pl-P4086085","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：super关键字也可以用在构造方法中，其功能为调用（）的构造方法。","opts":[],"ans":null,"explain":"super关键字也可以用在构造方法中，其功能为调用父类的构造方法。\n父类"},{"id":"java13215-pl-P4086086","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"程序填空题：调用父类的构造方法。 class Employee{ String name; public Employee(String s){ ① ; } } class Manager extends Employee{ String department; public Manager(String s,String d){ ② ; department =d; } }","opts":[],"ans":null,"explain":"①name　=s<br/>②super(s)"},{"id":"java13215-pl-P4086087","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：静态类型也称为（），是在代码编译时确定下来的。","opts":[],"ans":null,"explain":"静态类型也称为引用类型，是在代码编译时确定下来的。\n引用类型"},{"id":"java13215-pl-P4086088","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：被标记为final的类将不能被继承，这样的类称为（）或终态类。","opts":[],"ans":null,"explain":"被标记为final的类将不能被继承，这样的类称为终极类或终态类。\n终极类"},{"id":"java13215-pl-P4086089","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：在Java中可以通过关键字abstract把一个类定义为抽象类，每一个未被定义具体实现的方法也应标记为abstract，这样的方法称为（）。","opts":[],"ans":null,"explain":"在Java中可以通过关键字abstract把一个类定义为抽象类，每一个未被定义具体实现的方法也应标记为abstract，这样的方法称为抽象方法。\n抽象方法"},{"id":"java13215-pl-P4086090","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：接口仅仅说明了一种数据存储结构中存在存入和（）这样两种操作，并没有涉及具体实现。","opts":[],"ans":null,"explain":"接口仅仅说明了一种数据存储结构中存在存入（put）和取出（get）这样两种操作，并没有涉及具体实现。\n取出（或get）"},{"id":"java13215-pl-P4086091","type":"sa","tier":"创新","conf":"adapt","chap":"第6章","q":"填空题：在接口中定义的成员变量都默认为（）变量。","opts":[],"ans":null,"explain":"在接口中定义的成员变量都默认为终极静态变量，即系统会为其自动添加final和static这两个关键字，并且对该变量必须设置初值。\n终极静态"},{"id":"java13215-pl-P4086092","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：从数据流中读取数据时，必须有一个（）与该数据流相连。","opts":[],"ans":null,"explain":"从数据流中读取数据时，必须有一个数据源与该数据流相连。\n数据源"},{"id":"java13215-pl-P4086093","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：最初的版本中，java.io包中的流只有普通的字节流，即以（）为基本处理单位的流。","opts":[],"ans":null,"explain":"最初的版本中，java.io包中的流只有普通的字节流，即以byte为基本处理单位的流。\nbyte（或字节）"},{"id":"java13215-pl-P4086094","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：java.io包中所有输入数据流都是从抽象类（）继承而来的，并且实现了其中的所有方法，包括读取数据、标记位置、重置读写指针、获取数据量等。","opts":[],"ans":null,"explain":"java.io包中所有输入数据流都是从抽象类InputStream继承而来的，并且实现了其中的所有方法，包括读取数据、标记位置、重置读写指针、获取数据量等。\nInputStream"},{"id":"java13215-pl-P4086095","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述输入数据流中提供的主要数据操作方法。","opts":[],"ans":null,"explain":"输入数据流中提供的主要数据操作方法如下：<br/>（1）int　read（）：从输入流中读取一个字节的二进制数据。<br/>（2）int　read（byte[　]b）：将多个字节读到数组中，填满整个数组。<br/>（3）int　read（byte[　]b，int　off，intlen）：从输入流中读取长度为len的数据，从数组b中下标为off的位置开始放置读入的数据，读取完成后返回读取的字节数。<br/>（4）void　close（）：关闭数据流。<br/>（5）int　available（）：返回目前可以从数据流中读取的字节数（但实际的读操作所读取的字节数可能大于该返回值）。<br/>（6）long　skip（long　1）：跳过数据流中指定数量的字节不读，返回值表示实际跳过的字节数。"},{"id":"java13215-pl-P4086096","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述在支持回推操作的数据流中经常用到的方法。","opts":[],"ans":null,"explain":"（1）boolean　markSupported（）：用于测试数据流是否支持回推操作，当一个数据流支持mark（）和reset（）方法时返回true，否则返回false。<br/>（2）void　mark（int　markarea）：用于标记数据流的当前位置，并划出一个缓冲区，其大小至少为指定参数的大小。<br/>（3）void　reset（）：将输入流重新定位到对此流最后调用mark方法时的位置。"},{"id":"java13215-pl-P4086097","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：java.io包中输出数据流大多是从抽象类（）继承而来。","opts":[],"ans":null,"explain":"与输入流类似，java.io包中输出数据流大多是从抽象类OutputStream继承而来，并且实现了其中的所有方法。\nOutputStream"},{"id":"java13215-pl-P4086098","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述输出数据流中提供的主要数据操作方法。","opts":[],"ans":null,"explain":"输出数据流中提供的主要数据操作方法如下：<br/>（1）voidwrite（inti）：将字节i写入数据流中，它只输出所读入参数的最低8位。该方法是抽象方法，需要在其输出流子类中加以实现，然后才能使用。<br/>（2）void　write（byteb[　]）：将数组b[]中的全部b.length个字节写入数据流。<br/>（3）void　write（byteb[　]，intoff，intlen）：将数组b[　]中从下标off开始的len个字节写入数据流。元素b[off]是此操作写入的第一个字节，b[off+len-1]是此操作写入的最后一个字节。<br/>（4）voidclose（）：当结束对输出数据流的操作时应该将其关闭。<br/>（5）void　flush（）：刷新此输出流并强制写出所有缓冲的输出字节。"},{"id":"java13215-pl-P4086099","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：采用（）可以降低不同硬件设备之间速度的差异，提高I/O操作的效率。","opts":[],"ans":null,"explain":"采用缓冲区数据流可以降低不同硬件设备之间速度的差异，提高I/O操作的效率。\n缓冲区数据流"},{"id":"java13215-pl-P4086100","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：以下代码段将一个java.util.Date对象实例写入文件。 Date d = new Date(); FileOutputStream f = new FileOutputStream(&quot;date.ser&quot;); ObjectOutputStream s=new ObjectOutputStream(f); try{ s. ① ; s. ② ; }catch(IOException e){ e.printStackTrace(); }","opts":[],"ans":null,"explain":"①writeObject(d)<br/>②close()"},{"id":"java13215-pl-P4086101","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：以下程序将当前日期及时间作为对象实例写入date.dat文件中。 import java.io.*; import java.util.Date; public class Test{ public static void main(String[] args){ Date d = new Date(); try{ FileOutputStream f=new FileOutputStream(&quot;date.dat&quot;); ObjectOutputStream s= ① ; s.writeObject(d); s.close(); }catch(FileNotFoundException e){ e.printStackTrace(); }catch( ② ){ e.printStackTrace(); }","opts":[],"ans":null,"explain":"①new　ObjectOutputStream(f)<br/>②IOException　e"},{"id":"java13215-pl-P4086102","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：以下代码段将一个java.util.Date对象实例读对象流文件。 Date d = ① ; FilelnputStream f = new FilelnputStream(&quot;date.ser&quot;); ObjectInputStream s = new ObjectInputStream(f); try{ d =(Date)s. ② ; s.close(); }catch(IOException e){ e.printStackTrace(); } System.out.println(&quot;Date serialized at &quot; + d);","opts":[],"ans":null,"explain":"①null<br/>②readObject()"},{"id":"java13215-pl-P4086103","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：在Java中，允许可序列化的对象通过（）进行传输。","opts":[],"ans":null,"explain":"在Java中，允许可序列化的对象通过对象流进行传输。\n对象流"},{"id":"java13215-pl-P4085971","type":"sa","tier":"拔高","conf":"adapt","chap":"第6章","q":"程序分析题：编译运行下面的程序，结果是什么？ public class A{ public static void main(String[] args)( B b = new B(); b.test(); } void test(){ System.out.print(&quot;A&quot;); } } class B extends A{ void test(){ super.test(); System.out.print(&quot;B&quot;); } }","opts":[],"ans":null,"explain":"代码可以编译运行，并输出结果AB"},{"id":"java13215-pl-P4085972","type":"sa","tier":"拔高","conf":"adapt","chap":"第6章","q":"程序分析题：阅读以下程序，请写出该程序的输出结果。 class Tree{ String n; boolean isT; Tree (String name,boolean t){n=name;isT=t;} public void printTree(String str){ System.out.println(); System.out.print(str); System.out.print(&quot;Name:&quot;+n+&quot;,&quot;); System.out.print(&quot;is Tree:&quot;+isT); } } class Poplar extends Tree{ public boolean isP; Poplar(String n,boolean f,boolean c){super(n,f);isP=c;} public void printTree(String str){ super.printTree(str); System.out.println(&quot;,Coni:&quot;+isP); } } public class Test{ public static void main(String[] args){ Tree tOb1= new Tree(&quot;Cabbage&quot;,false); Poplar tOb2=new Poplar(&quot;Poplar&quot;,true,tre); tOb1.printTree(&quot;cabbage:&quot;); tOb2.printTree(&quot;poplar:&quot;); } }","opts":[],"ans":null,"explain":"cabbage:Name;Cabbage,is　Tree:false<br/>poplar:Name:Poplar,is　Tree:true,Coni:true"},{"id":"java13215-pl-P4085973","type":"sa","tier":"拔高","conf":"adapt","chap":"第6章","q":"程序分析题：阅读以下程序，请写出该程序的输出结果。 public class SuperClass{ public static void main(String[] args){ new SuperClass(0);new SubClass ();new SubClass(1); } SuperClass(){System.out.print(&quot;A\\n&quot;);} SuperClass (int i){this();System.out.print(&quot;AA\\n&quot;);} } class SubClass extends SuperClass{ SubClass (){super();System.out.print(&quot;B\\n&quot;);} SubClass (int i){super();System.out.print(&quot;BB\\n&quot;);} }","opts":[],"ans":null,"explain":"A<br/>AA<br/>A<br/>B<br/>A<br/>BB"},{"id":"java13215-pl-P4085896","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在英语国家中，字节编码采用（）协议。","opts":["A. UTF-8","B. GB2312","C. ISO 8859_1","D. GBK"],"ans":2,"explain":"在英语国家中，字节编码采用ISO 8859_1协议。"},{"id":"java13215-pl-P4085897","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"File对象不能用来（）。","opts":["A. 命名文件","B. 查询文件属性","C. 读写文件","D. 删除目录"],"ans":3,"explain":"File类可以用来描述一个目录，对其进行的操作也与文件相同，只是不能改变目录名，也不能进行删除。"},{"id":"java13215-pl-P4085898","type":"sc","tier":"基础","conf":"adapt","chap":"第7章","q":"在Java中，要创建一个RandomAccessFile对象，以下哪种方法是可用的？（）","opts":["A. 只能使用文件名来创建","B. 只能使用File对象来创建","C. 既可以使用文件名，也可以使用File对象来创建","D. 都不能用来创建RandomAccessFile对象"],"ans":2,"explain":"创建一个随机访问文件有以下两种方法供选择。 （1）使用文件名 （2）使用文件对象"},{"id":"java13215-pl-P4085899","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"以下不属于java的图形用户界面内容的包是（）。","opts":["A. java.awt","B. javax.swing","C. java.awt.event","D. java.io"],"ans":3,"explain":"图形用户界面（Graphical User Interface，GUI）是大多数程序不可缺少的部分，Java的图形用户界面由各种组件构成，在java.awt包和javax.swing包中定义了多种用于创建图形用户界面的组件类。"},{"id":"java13215-pl-P4085900","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在设计图形用户界面（GUI）时，以下哪个步骤不属于常见的三个步骤？（）","opts":["A. 选取组件","B. 设计布局","C. 编写代码","D. 响应事件"],"ans":2,"explain":"设计图形用户界面时一般有3个步骤，分别是选取组件、设计布局及响应事件。"},{"id":"java13215-pl-P4085901","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"java.awt包中用（）表示按钮。","opts":["A. Button","B. JButton","C. Label","D. JLabel"],"ans":0,"explain":"标签和按钮，在java.awt包中分别用Label和Button表示，而在javax.swing包中则分别用JLabel和JButton表示，多数Swing组件以字母“J”开头。"},{"id":"java13215-pl-P4085902","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"javax.swing包中用（）表示标签。","opts":["A. Button","B. JButton","C. Label","D. JLabel"],"ans":3,"explain":"标签和按钮，在java.awt包中分别用Label和Button表示，而在javax.swing包中则分别用JLabel和JButton表示，多数Swing组件以字母“J”开头。"},{"id":"java13215-pl-P4085903","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java中，Swing组件和AWT组件的“轻量级”和“重量级”描述与以下哪个因素有关？（）","opts":["A. 组件的渲染速度","B. 组件所使用的代码类型","C. 组件是否包含本地代码","D. 组件的视觉效果"],"ans":2,"explain":"不包含本地代码的Swing组件被称为“轻量级”组件，而包含本地代码的AWT组件被称为“重量级”组件。"},{"id":"java13215-pl-P4085904","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java中，图形用户界面的基本构建块是（）。","opts":["A. 容器","B. 事件","C. 组件","D. 布局"],"ans":2,"explain":"Java的图形用户界面由各种组件构成，组件是构成图形用户界面的基本元素。"},{"id":"java13215-pl-P4085905","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的图形用户界面（GUI）编程中，作为容器组件的是（）。","opts":["A. JButton","B. JFrame","C. JLabel","D. JTextField"],"ans":1,"explain":"按钮（JButton）、文本输入框（JTextField）、标签（JLabel）等都是组件。框架（Frame）、面板（Panel）等组件称为容器（Container），它们是特殊的组件，其中还可以嵌套组件，各种组件（包括容器）可以通过add（）方法添加到容器中。"},{"id":"java13215-pl-P4085906","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，哪个类是所有容器类的父类，并且定义了容器的共有操作？（）","opts":["A. Component","B. Container","C. JFrame","D. JPanel"],"ans":1,"explain":"Java为所有容器类定义了父类Container，容器的共有操作都定义在Container类中。"},{"id":"java13215-pl-P4085907","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"（）是一个带有标题行和控制按钮（最小化、恢复/最大化、关闭）的独立窗口。","opts":["A. JFrame","B. JApplet","C. JDialog","D. JWindow"],"ans":0,"explain":"JFrame是一个带有标题行和控制按钮（最小化、恢复/最大化、关闭）的独立窗口，有时称为框架创建应用程序时需要使用JFrame。"},{"id":"java13215-pl-P4085908","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"创建小应用程序时使用（），它被包含在浏览器窗口中。","opts":["A. JFrame","B. JApplet","C. JDialog","D. JWindow"],"ans":1,"explain":"创建小应用程序时使用JApplet，它被包含在浏览器窗口中。"},{"id":"java13215-pl-P4085909","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"创建对话框时使用（）。","opts":["A. JFrame","B. JApplet","C. JDialog","D. JWindow"],"ans":2,"explain":"创建对话框时使用JDialog。"},{"id":"java13215-pl-P4085910","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"顶层容器默认内容窗格的布局管理器是（）。","opts":["A. BorderLayout","B. FlowLayout","C. GridLayout","D. CardLayou"],"ans":0,"explain":"顶层容器默认内容窗格的布局管理器是BorderLayout，而JPanel默认的布局管理器是FlowLayout，因此需要为JPanel实例设置一个BorderLayout布局管理器。"},{"id":"java13215-pl-P4085911","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"JPanel默认的布局管理器是（）。","opts":["A. BorderLayout","B. FlowLayout","C. GridLayout","D. CardLayou"],"ans":1,"explain":"顶层容器默认内容窗格的布局管理器是BorderLayout，而JPanel默认的布局管理器是FlowLayout，因此需要为JPanel实例设置一个BorderLayout布局管理器。"},{"id":"java13215-pl-P4085912","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，Scrollbar类的构造函数Scrollbar(int orientation)中的参数orientation用于指示（）。","opts":["A. 滚动条的宽度","B. 滚动条的高度","C. 滚动条的颜色","D. 滚动条的方向"],"ans":3,"explain":"Scrollbar（int orientation）：构造一个具有指定方向的新滚动条。orientation指示滚动条的方向，其值是Scrollbar.HORIZONTAL或Scrollbar.VERTICAL，分别指示滚动条是水平滚动条或垂直滚动条。"},{"id":"java13215-pl-P4085913","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，JLabel的构造方法中，用于指定水平对齐方式的参数horizontalAlignment可以取哪些值？（）","opts":["A. JLabel.TOP, JLabel.BOTTOM, JLabel.CENTER","B. JLabel.LEFT, JLabel.RIGHT, JLabel.CENTER","C. JLabel.NORTH, JLabel.SOUTH, JLabel.CENTER","D. JLabel.EAST, JLabel.WEST, JLabel.CENTER"],"ans":1,"explain":"构造方法中，表示水平对齐方式的int型参数horizontalAlignment的取值可为JLabel.LEFT、JLabel.RIGHT和JLabel.CENTER常量，分别表示左对齐、右对齐和居中对齐。"},{"id":"java13215-pl-P4085914","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，如果你想要修改JLabel上显示的文本信息，你应该使用哪个方法？（）","opts":["A. setIcon(Icon icon)","B. setText(String text)","C. getText(String text)","D. modifyText(String text)"],"ans":1,"explain":"程序中可以使用setText（String text）方法修改显示在标签上的文本信息，也可以使用setIcon（Icon icon）方法修改标签上的图标。"},{"id":"java13215-pl-P4085915","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，以下哪个组件不是AbstractButton的子类或间接子类？（）","opts":["A. JButton","B. JToggleButton","C. JCheckBox","D. JList"],"ans":3,"explain":"按钮（JButton）是Java图形用户界面的基本组件之一，经常用到的按钮有4种形式：JButton、JToggle- Button、JCheckBox和JRadioButton，它们均是AbstractButton的子类或间接子类。"},{"id":"java13215-pl-P4085916","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"下列选项中不属于组控件包含的按钮是（）。","opts":["A. 单选按钮","B. 事件按钮","C. 复选按钮","D. 切换按钮"],"ans":1,"explain":"除了普通按钮JButton外，还有切换按钮（JToggleButton）、复选按钮（JCheckBox）和单选按钮（JRadioButton）。"},{"id":"java13215-pl-P4085917","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"JRadioButton被称为（）。","opts":["A. 单选按钮","B. 事件按钮","C. 复选按钮","D. 切换按钮"],"ans":0,"explain":"JCheckBox被称为复选按钮，而JRadioButton被称为单选按钮。"},{"id":"java13215-pl-P4085918","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在默认情况下，FlowLayout将组件（）放置在容器的某一行上。","opts":["A. 居中","B. 靠上","C. 靠右","D. 靠左"],"ans":0,"explain":"在默认情况下，FlowLayout将组件居中放置在容器的某一行上。"},{"id":"java13215-pl-P4085919","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，使用BorderLayout管理的容器中，哪个常量用于表示容器的中部区域？（）","opts":["A. BorderLayout.NORTH","B. BorderLayout.SOUTH","C. BorderLayout.WEST","D. BorderLayout.CENTER"],"ans":3,"explain":"每个由BorderLayout管理的容器被划分成5个区域，分别代表容器的上部（North）、下部（South）、左部（West）、右部（East）和中部（Center），分别使用常量BorderLayout.NORTH、BorderLayout.SOUTH、BorderLayout.WEST、BorderLayout.EAST和BorderLayout.CENTER来表示。"},{"id":"java13215-pl-P4085920","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"GridLayout是Java Swing中哪种类型的布局管理器？（）","opts":["A. 流式布局","B. 边框布局","C. 网格式布局","D. 卡片布局"],"ans":2,"explain":"GridLayout是一种网格式的布局管理器，它将容器空间划分成若干行乘若干列的网格，组件依次放入其中，每个组件占据一格。"},{"id":"java13215-pl-P4085921","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，使用BoxLayout布局管理器时，哪个参数用于指定组件的排列方向，是水平排列还是垂直排列？（）","opts":["A. target","B. axis","C. orientation","D. direction"],"ans":1,"explain":"Container型参数target指明是为哪个容器设置此BoxLayout布局管理器；int型参数axis指明组件的排列方向，通常使用的是常量BoxLayout.X_AXIS或BoxLayout.Y_AXIS，分别表示按水平方向排列或按垂直方向排列。"},{"id":"java13215-pl-P4086104","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：Java通过字符输入流和（），实现了对不同平台之间数据流中数据的转换。","opts":[],"ans":null,"explain":"Java通过字符输入流和字符输出流，实现了对不同平台之间数据流中数据的转换。\n字符输出流"},{"id":"java13215-pl-P4086105","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：Java提供一种新的数据流处理方案，称作字符输入流和（）。","opts":[],"ans":null,"explain":"Java提供一种新的数据流处理方案，称作字符输入流（Reader）和字符输出流（Writer）。\n字符输出流（或Writer）"},{"id":"java13215-pl-P4086106","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述字符输入流提供的方法。","opts":[],"ans":null,"explain":"字符输入流提供的方法包括：<br/>（1）void　close（）。<br/>（2）void　mark（int　readAheadLimit）。<br/>（3）boolean　markSupported（）。<br/>（4）int　read（）。<br/>（5）int　read（char[　]cbuf）。<br/>（6）int　read（char[　]cbuf，int　off，int　len）。<br/>（7）boolean　ready（）。<br/>（8）void　reset（）。<br/>（9）long　skip（long　n）。"},{"id":"java13215-pl-P4086107","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述字符输出流提供的方法。","opts":[],"ans":null,"explain":"字符输出流提供的方法包括：<br/>（1）void　close（）。<br/>（2）void　flush（）。<br/>（3）void　write（char[　]　cbuf）。<br/>（4）void　write（char[　]　cbuf，int　off，int　len）。<br/>（5）void　write（int　c）。<br/>（6）void　write（String　str）。<br/>（7）void　write（String　str，int　off，int　len）。"},{"id":"java13215-pl-P4086108","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：BufferedReader的方法，从输入流中读取一行字符，行结束标志为（）、‘\\r’或两者一起。","opts":[],"ans":null,"explain":"public String readLine（）：BufferedReader的方法，从输入流中读取一行字符，行结束标志为‘\\n’、‘\\r’或两者一起。\n‘\\n’"},{"id":"java13215-pl-P4086109","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：从标准输入通道读取字符串信息，然后进行输出。 import java.io.*; public class CharInput{ public static void main(String args[]) throws IOException{ String s; InputStreamReader ir; BufferedReader in; ir = new InputStreamReader( ① ); in = new ② ; while ((s = in.readLine()) ! = null) System.out.println(&quot;Read:&quot;+s); } }","opts":[],"ans":null,"explain":"①System.in<br/>②BufferedReader(ir)"},{"id":"java13215-pl-P4086110","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：Java中，在字节流和字符流之间起到中介作用，充当字节流和字符流输入流之间接口的类是（）。","opts":[],"ans":null,"explain":"Java中，在字节流和字符流之间起到中介作用，充当字节流和字符流输入流之间接口的类是InputStreamReader。\nInputStreamReader"},{"id":"java13215-pl-P4086111","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"请写出为文本文件abc.txt创建BufferedReader对象in的代码。","opts":[],"ans":null,"explain":"BufferedReader　in=new　BufferedReader(new　FileReader(“abc.txt&quot;));"},{"id":"java13215-pl-P4086112","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：从标准输入通道读取字符串信息，然后进行输出。 import java.io.*; public class CharInput{ public static void main(String args[]) ① IOException{ String s; InputStreamReader ir; BufferedReader in; ir = new InputStreamReader( ② ); in = new BufferedReader(ir); while ((s = in.readLine())!=null) System.out.println(Read:&quot;+s); } }","opts":[],"ans":null,"explain":"①throws<br/>②System.in"},{"id":"java13215-pl-P4086113","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"程序填空题：从标准输入通道读取字符串信息，然后进行输出。 import java.io.*; public class CharInput{ public static void main(String args[])throws IOException{ String s; InputStreamReader ir; BufferedReader in; ir = new InputStreamReader(System.in); in = ① ; while ((s = in.readLine())!=null) System.out.println(Read:&quot;+ ② ); } }","opts":[],"ans":null,"explain":"①new　BufferedReader(ir)<br/>②s"},{"id":"java13215-pl-P4086114","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：创建（）类的对象后，可以应用其中的相关方法来获取文件的信息。","opts":[],"ans":null,"explain":"创建File类的对象后，可以应用其中的相关方法来获取文件的信息。\nFile"},{"id":"java13215-pl-P4086115","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"简述常用文件信息和方法。","opts":[],"ans":null,"explain":"（1）long　lastModified（）：获取文件最后修改时间。<br/>（2）long　length（）：获取文件长度。<br/>（3）boolean　delete（）：删除文件对象指向的文件，成功则返回true，否则返回false。"},{"id":"java13215-pl-P4086116","type":"sa","tier":"创新","conf":"adapt","chap":"第7章","q":"填空题：参数（）决定是以只读方式还是以读写方式访问文件。","opts":[],"ans":null,"explain":"参数mode决定是以只读方式（“r”）还是以读写方式（“rw”）访问文件。\nmode"},{"id":"java13215-pl-P4086117","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：Swing组件与AWT组件最大的不同是Swing组件在实现时不包含任何（）代码。","opts":[],"ans":null,"explain":"Swing组件与AWT组件最大的不同是Swing组件在实现时不包含任何本地代码，因此Swing组件可以不受硬件平台的限制，而具有更多的功能。\n本地"},{"id":"java13215-pl-P4086118","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：Java抽象窗口工具集的简称（）。","opts":[],"ans":null,"explain":"Java抽象窗口工具集的简称AWT。\nAWT"},{"id":"java13215-pl-P4086119","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：容器组件是指可以包含其他组件的组件，又分为（）和一般用途容器。","opts":[],"ans":null,"explain":"所谓容器组件是指可以包含其他组件的组件，又分为顶层容器和一般用途容器。\n顶层容器"},{"id":"java13215-pl-P4086120","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：Swing中提供了4种顶层容器，分别为（）、JApplet、JDialog和JWindow。","opts":[],"ans":null,"explain":"Swing中提供了4种顶层容器，分别为JFrame、JApplet、JDialog和JWindow。\nJFrame"},{"id":"java13215-pl-P4086121","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：JFrame可以改变窗口大小，在刚创建时，它的大小为0，并且不可见，需要使用（）。","opts":[],"ans":null,"explain":"JFrame可以改变窗口大小，在刚创建时，它的大小为0，并且不可见，需要使用frame.pack（）。\nframe.pack（）"},{"id":"java13215-pl-P4086122","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：通过顶层容器的（）方法获得其默认的内容窗格。","opts":[],"ans":null,"explain":"第一种方法是通过顶层容器的getContentPane（）方法获得其默认的内容窗格。getContentPane（）方法的返回值类型为java.awt.Container，它仍然是一个容器。然后将组件添加到内容窗格中。\ngetContentPane（）"},{"id":"java13215-pl-P4086123","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：普通面板和（）都是用途广泛的容器。","opts":[],"ans":null,"explain":"普通面板（JPanel）和滚动面板（JScrollPane）都是用途广泛的容器。\n滚动面板（或JScrollPane）"},{"id":"java13215-pl-P4086124","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"简述JPanel类常用的构造方法有哪些。","opts":[],"ans":null,"explain":"JPanel类常用的构造方法有:<br/>（1）JPanel（）：创建具有FlowLayout布局的新面板。<br/>（2）JPanel（LayoutManager　layout）：创建具有指定布局管理器的新面板。"},{"id":"java13215-pl-P4086125","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"程序填空题：以下MyPanel类在面板上放置一个列表，当单击列表中某个选项时，该选项的值保存在seleItem中。 class MyPanel extends JPanel implements ListSelectionListener{ private String seleltem=null; JList list; MyPanel(String[] listItems){ list=new JList(listItems); list.setVisibleRowCount(2); list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION); list.addListSelectionListener(this); JScrollPane jsp=new JScrollPane(list); add(jsp); } public String getSeleltem(){return seleltem;} public void valueChanged(① e){ if (e.getSource()==list){ seleltem = list.② .toString(); } } }","opts":[],"ans":null,"explain":"①ListSelectionEvent<br/>②getSelectedValue()"},{"id":"java13215-pl-P4086126","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"简述JButton是最简单的按钮，常用的构造方法。","opts":[],"ans":null,"explain":"JButton是最简单的按钮，常用的构造方法有：<br/>（1）JButton（）：创建一个既没有显示文本也没有图标的按钮。<br/>（2）JButton（Icon　icon）：创建一个没有显示文本但有图标的按钮。<br/>（3）JButton（String　text）：创建一个有显示文本但没有图标的按钮。<br/>（4）JButton（String　text，Icon　icon）：创建一个既有显示文本又有图标的按钮。"},{"id":"java13215-pl-P4086127","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：JToggleButton是具有两种状态的按钮，即（）和未选中状态。","opts":[],"ans":null,"explain":"JToggleButton是具有两种状态的按钮，即选中状态和未选中状态。\n选中状态"},{"id":"java13215-pl-P4086128","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：构造方法中如果没有指定按钮的初始状态，则默认处于（）状态。","opts":[],"ans":null,"explain":"构造方法中如果没有指定按钮的初始状态，则默认处于未选中状态。\n未选中"},{"id":"java13215-pl-P4086129","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：在ActionEvent、ItemEvent等事件类对象中，都提供了（）方法，可以获取事件源。","opts":[],"ans":null,"explain":"在ActionEvent、ItemEvent等事件类对象中，都提供了gelSource（）方法，可以获取事件源，该方法的返回值类型为Object；需要进行类型转换，例如下面命令将Object类型转换为JRadioButton类型。\ngelSource（）"},{"id":"java13215-pl-P4086130","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：刚创建的框架Frame还不能显示，可以使用（）进行显示。","opts":[],"ans":null,"explain":"刚创建的框架Frame还不能显示，可以使用frame.setVisible（true）进行显示。\nframe.setVisible（true）"},{"id":"java13215-pl-P4086131","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：在javax.swing包中定义了一个专门使用BoxLayout的特殊容器—（）类。","opts":[],"ans":null,"explain":"在javax.swing包中定义了一个专门使用BoxLayout的特殊容器—Box类，Box类中提供了创建Box实例的静态方法。\nBox"},{"id":"java13215-pl-P4085975","type":"sa","tier":"拔高","conf":"adapt","chap":"第8章","q":"程序分析题：阅读以下程序，请回答下列问题： (1)程序运行时，在文本域中输入30并回车，程序输出什么样的图形？该图形是什么颜色的？ (2)包围该图形的最小矩形的宽和高分别是多少像素？ import javax.swing.*; import java.awt.*; import java.awt.event.*; class MyPanel extends JPanel implements ActionListener{ JTextField text; int width,height; int posX,posY,radius; MyPanel(){ setLayout(new BorderLayout()); text =new JTextField(10); add(text,BorderLayout.NORTH); text.addActionListener(this); } public void paintComponent(Graphics g){ g.setColor(Color.red); g.drawOval(posX,posY,radius * 2,radius * 2); } public void actionPerformed(ActionEvent e){ if (e.getSource()==text){ int r=Integer.parseInt(text.getText()); width=this.getWidth(); height=this.getHeight(); posX = width/2-r; posY = height/2-r; radius =r; repaint(); } } } public class Test{ public static void main(String[] args){ JFrame myFrame=new JFrame(); myFrame.getContentPane().add(new MyPanel()); myFrame.setSize(200,250); myFrame.setLocation(100,100); myFrame.setVisible(true); } }","opts":[],"ans":null,"explain":"(1)输出一个空心圆，该图形的颜色是红色的。<br/>(2)包围该图形的最小矩形的宽和高都是60像素。"},{"id":"java13215-pl-P4085087","type":"calc","tier":"创新","conf":"adapt","chap":"第8章","q":"程序设计题：请使用JFrame创建一个应用程序，运行该程序，将在屏幕上显示出一个窗口，窗口中有一个按钮，如图1-1所示。 [图]https://file.mshiedu.com/exam/2024-3-22/uBVidY0uKVLCbRJ2Ldzyx0UIoCk36DfbMzcTglZphb8TKeg2bo.png 图1-1 程序执行结果 [图]https://file.mshiedu.com/exam/2024-3-22/D4wyBPd7P58MziNOOtEOCEjzpWXmAM4gKPmUe9PtiLyRmhIn5g.png","opts":[],"ans":null,"explain":"<br/>JFrame frame=new JFrame(&quot;JFrameDemo&quot;);<br/>JButton button=new JButton(&quot;Press me&quot;);<br/>frame.getContentPane().add(button,BorderLayout.CENTER);<br/>frame.pack();<br/>frame.setVisible(true);<br/>frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);"},{"id":"java13215-pl-P4085974","type":"calc","tier":"创新","conf":"adapt","chap":"第8章","q":"程序设计题：创建一个黄色普通面板，通过add（）方法在面板中添加一个按钮，然后将该面板添加到Frame的一个实例中，JFrame实例的背景色被设置为蓝绿色。 import java.awt.*; import javax.swing.*; public class FrameWithPanel{ public static void main(String args[]){ //请在此处填写应编写的代码 } }","opts":[],"ans":null,"explain":"JFrame　frame=new　JFrame(&quot;Frame　with　Panel&quot;);<br/>　　Container　contentPane=frame.getContentPane();<br/>　　contentPane.setBackground(Color.CYAN);<br/>　　JPanel　panel　=　new　JPanel();<br/>　　panel.setBackground(Color.yellow);<br/>　　JButton　button　=　new　JButton(&quot;Press　me&quot;);<br/>　　panel.add(button);<br/>　　contentPane.add(panel,BorderLayout.SOUTH);<br/>　　frame.setSize(300,200);<br/>　　frame.setVisible(true);<br/>　　frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);"},{"id":"java13215-pl-P4085922","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Swing库中，为了接收并处理用户事件，组件需要注册哪种类型的程序？（）","opts":["A. 事件生成器","B. 事件处理器","C. 事件侦听程序","D. 事件调度器"],"ans":2,"explain":"为了接收并处理某类用户事件，组件必须注册相应的事件处理程序，这种事件处理程序称为事件侦听程序（Listener，也称为侦听器），它是实现了对应侦听程序接口的一个类。"},{"id":"java13215-pl-P4085923","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在RGB颜色模型中，每种颜色是由哪三个值来指定的？（）","opts":["A. 红-黄-蓝","B. 红-绿-紫","C. 红-绿-蓝","D. 红-黄-绿"],"ans":2,"explain":"另一种方法是通过红、绿、蓝三原色的值来组合。每种颜色由三个值来指定，它们一起称为RGB值，RGB分别代表红-绿-蓝。各个值表示对应原色的相对值，使用1个字节（8位）来保存，取值范围为0~255。三种原色的值合在一起来决定实际的颜色值。"},{"id":"java13215-pl-P4085924","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java语言中，文字字型有三个要素，分别是（）。","opts":["A. 字体、字形和字号","B. 字形、颜色和字号","C. 字体、风格和字号","D. 字体、字形和颜色"],"ans":2,"explain":"文字字型有字体、样式及字号3个要素。"},{"id":"java13215-pl-P4085925","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的AWT中，哪个类是所有图形上下文的抽象父类，提供了绘制图形和图像的基础功能？（）","opts":["A. Component","B. Container","C. Image","D. Graphics"],"ans":3,"explain":"Graphics类是所有图形上下文的抽象父类，允许应用程序在组件以及屏幕图像上进行绘制。"},{"id":"java13215-pl-P4085926","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在图形绘制中，通常存在两种主要的绘图模式，它们是（）。","opts":["A. 正常模式和叠加模式","B. 异或模式和叠加模式","C. 正常模式和异或模式","D. 透明模式和异或模式"],"ans":2,"explain":"绘图模式主要有两种，分别是正常模式和异或模式。"},{"id":"java13215-pl-P4085927","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的Graphics类中，用于绘制多边形和填充多边形的方法分别是（）。","opts":["A. drawPolygon() 和 fillPolygon()","B. drawShape() 和 fillShape()","C. drawArea() 和 fillArea()","D. drawClosedFigure() 和 fillClosedFigure()"],"ans":0,"explain":"使用Graphics类的方法可以绘制多边形，这类似于矩形和椭圆的绘制。和其他图形一样，多边形也可以画成填充的或不填充的。画多边形的方法分别是drawPolygon（）和fillPolygon（）。"},{"id":"java13215-pl-P4085928","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在图形绘制中，当两条线段交汇时，默认的连接方式是（）。","opts":["A. CAP_BUTT","B. CAP_ROUND","C. JOIN_BEVEL","D. JOIN_MTTER"],"ans":3,"explain":"端点样式cap的值有CAP_BUTT（无修饰）、CAP_ROUND（半圆形末端）和CAP_SQUARE（方形末端，默认值）。两线段交汇处的连接方式join的值有JOIN_BEVEL（无修饰）、JOIN_MTTER（尖形末端，默认值）和JOIN_ROUND（圆形末端）。"},{"id":"java13215-pl-P4085929","type":"sc","tier":"基础","conf":"adapt","chap":"第8章","q":"在Java的java.awt.geom包中，用于创建椭圆形状对象的类是（）。","opts":["A. Line2D","B. RoundRectangle2D","C. Ellipse2D","D. Arc2D"],"ans":2,"explain":"在java.awt.geom包中声明的一系列类，分别用于创建各种几何图形对象。这些类主要有Line2D线段类、RoundRectangle2D圆角矩形类、Ellipse2D椭圆类、Arc2D圆弧类、QuadCurve2D二次曲线类和CubicCurve2D三次曲线类。"},{"id":"java13215-pl-P4085930","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"JComboBox是Java Swing中的一个组件，用于展示一个下拉式菜单。这种组件有两种形式，它们是（）。","opts":["A. 单选和多选","B. 水平和垂直","C. 不可编辑的和可编辑的","D. 有序和无序"],"ans":2,"explain":"组合框（JComboBox）是一个下拉式菜单，它有两种形式：不可编辑的和可编辑的。"},{"id":"java13215-pl-P4085931","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"表示组合框的类名是（）。","opts":["A. JComboBox","B. JList","C. JTextField","D. JTextArea"],"ans":0,"explain":"组合框（JComboBox）是一个下拉式菜单。"},{"id":"java13215-pl-P4085932","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing中，JList组件允许用户选择列表中的项。要设置JList的选择模式，即支持单项选择还是多项选择，可以使用哪个方法？（）","opts":["A. setSelectionType(int type)","B. setSelectionMode(int mode)","C. setChoiceMode(int mode)","D. setSelectionStyle(int style)"],"ans":1,"explain":"列表既支持单项选择也支持多项选择，可以使用JList中定义的setSelectionMode（int selectionMode）方法对列表的选择模式进行设置，其中int型参数selectionMode可为以下常量。"},{"id":"java13215-pl-P4085933","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing中，JTextField、JPasswordField和JTextArea等文本组件共享一个共同的父类，这个父类是（）。","opts":["A. JComponent","B. JTextComponent","C. AbstractTextComponent","D. TextComponent"],"ans":1,"explain":"在Swing中提供了文本域（JTextField）、口令输入域（JPasswordField）、文本区（JTextArea）等多个文本组件，这些文本组件有一个共同的父类——JTextComponent，在JTextComponent中定义了文本组件所共有的一些方法。"},{"id":"java13215-pl-P4085934","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"文本域（JTextField）是一个什么样的文本输入框？（）","opts":["A. 单行的文本输入框，用于输入少量文本","B. 多行的文本输入框，用于输入大量文本","C. 只能输入数字的文本输入框","D. 只能输入字母的文本输入框"],"ans":0,"explain":"文本域是一个单行的文本输入框，可用于输入少量文本。"},{"id":"java13215-pl-P4085935","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing中，要设置JTextField（文本域）为可编辑或不可编辑状态，应使用哪个方法？（）","opts":["A. setVisible(boolean)","B. setEnabled(boolean)","C. setEditable(boolean)","D. setReadOnly(boolean)"],"ans":2,"explain":"可以用setEditable（boolean）方法将文本域设定为可编辑或不可编辑状态。"},{"id":"java13215-pl-P4085936","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"文本区（JTextArea）是什么样的文本输入框？（）","opts":["A. 单行单列的文本输入框","B. 单行多列的文本输入框","C. 多行单列的文本输入框","D. 多行多列的文本输入框"],"ans":3,"explain":"文本区是一个多行多列的文本输入框。"},{"id":"java13215-pl-P4085937","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"菜单通常分为哪两种类型？（）","opts":["A. 下拉式菜单和滚动式菜单","B. 弹出式菜单和选择式菜单","C. 下拉式菜单和弹出式菜单","D. 静态菜单和动态菜单"],"ans":2,"explain":"菜单有下拉式菜单和弹出式菜单两种。"},{"id":"java13215-pl-P4085938","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"方法setMnemonic()的作用是（）。","opts":["A. 将组合框设置为可编辑的","B. 为菜单项设置加速键","C. 将组合框设置为不可编辑的","D. 为菜单项设置快捷键"],"ans":3,"explain":"快捷键也可以在菜单项被创建之后，通过setMnemonic（char mnemonic）方法进行设置。"},{"id":"java13215-pl-P4085939","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing的Menu类中，如果你想要在菜单项之间添加分隔线，你应该使用哪些方法？（）","opts":["A. addSeparator() 和 insertSeparator(int index)","B. addDivider() 和 insertDivider(int index)","C. addGap() 和 insertGap(int index)","D. addBreak() 和 insertBreak(int index)"],"ans":0,"explain":"在Menu类中定义有addSeparator（）和insertSeparator（int index）方法，通过这些方法，可以在某个菜单的各个菜单项间加入分隔线。"},{"id":"java13215-pl-P4085940","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在菜单项中，哪种类型的菜单项前面有一个小方框，而另一种前面有一个小圆圈？（）","opts":["A. 复选菜单项和单选菜单项","B. 复选菜单项和滚动菜单项","C. 单选菜单项和弹出菜单项","D. 滚动菜单项和弹出菜单项"],"ans":0,"explain":"复选菜单项和单选菜单项是两种特殊的菜单项，在复选菜单项前面有一个小方框，在单选菜单项前面有一个小圆圈。"},{"id":"java13215-pl-P4085941","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"由于复选菜单项（或单选菜单项）具有选中和不选中状态，因此在构造方法中可以用（）型参数指定菜单项的初始状态。","opts":["A. int","B. void","C. boolean","D. static"],"ans":2,"explain":"由于复选菜单项（或单选菜单项）具有选中和不选中状态，因此在构造方法中可以用boolean型参数指定菜单项的初始状态。"},{"id":"java13215-pl-P4085942","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在图形用户界面（GUI）中，哪种类型的对话框会阻止用户与其他窗口交互，直到该对话框被关闭？（）","opts":["A. 强制型对话框","B. 非强制型对话框","C. 模态对话框","D. 非模态对话框"],"ans":0,"explain":"对话框分为强制型和非强制型两种。强制型对话框被关闭之前，其他窗口无法接收任何形式的输入，也就是该对话过程不能被中断，这样的窗口也称为模式窗口。非强制型对话框可以中断对话过程，去响应对话框之外的事件。"},{"id":"java13215-pl-P4085943","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing中，如果你想要显示一个刚刚创建的对话框，你应该调用哪个方法？（）","opts":["A. setHidden(true)","B. setVisible(false)","C. setHidden(false)","D. setVisible(true)"],"ans":3,"explain":"刚刚创建的对话框是不可见的，需要调用setVisible（true）方法才能将其显示出来。当对话框不需要显示时，调用setVisible（false）方法可以隐藏对话框。"},{"id":"java13215-pl-P4085944","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing中，如果你想要显示一个标准对话框而不是创建一个自定义对话框，你应该使用哪个类？（）","opts":["A. JDialog","B. JOptionPane","C. JFrame","D. JWindow"],"ans":1,"explain":"JDialog类通常用于创建自定义的对话框，除此之外，在Swing中还提供了用于显示标准对话框的JOptionPane类。在JOptionPane类中定义了多个showXxxDialog形式的静态方法。"},{"id":"java13215-pl-P4085945","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在图形用户界面（GUI）中，哪种类型的对话框专门用于浏览和选择文件（或目录）？（）","opts":["A. 消息对话框","B. 文件对话框","C. 颜色选择对话框","D. 字体选择对话框"],"ans":1,"explain":"文件对话框是专门用于对文件（或目录）进行浏览和选择的对话框。"},{"id":"java13215-pl-P4085946","type":"sc","tier":"基础","conf":"adapt","chap":"第9章","q":"在Java Swing的文件对话框中，当用户选择了一个文件后，通常可以通过哪个方法来获取用户所选择的文件？（）","opts":["A. getSelectedFile()","B. getSelectedFiles()","C. getSelectedPath()","D. getSelectedPaths()"],"ans":0,"explain":"对于文件对话框中的事件，一般都无须进行处理。当用户进行文件选择之后，可以通过getSelectedFile（）方法取得用户所选择的文件。"},{"id":"java13215-pl-P4085947","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在程序执行期间，从程序入口开始，按照语句的顺序（包括顺序、分支和循环结构）完成相应指令，直到程序出口结束，这样的语句结构称为（）。","opts":["A. 线程","B. 进程","C. 程序","D. 任务"],"ans":1,"explain":"在程序要投入运行时，系统从程序入口开始按语句的顺序（其中包括顺序、分支和循环结构）完成相应指令直至结尾，从出口退出，整个程序结束。这样的语句结构称为进程，它是程序的一次动态执行，对应了从代码加载、执行至执行完毕的一个完整过程；或者说进程就是程序在处理机中的一次运行。"},{"id":"java13215-pl-P4085948","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"Java类库中的（）类允许创建这样的线程，并可控制所创建的线程。","opts":["A. java.util.Thread","B. java.lang.Runnable","C. java.lang.Thread","D. java.util.Concurrent"],"ans":2,"explain":"Java类库中的java.lang.Thread类允许创建这样的线程，并可控制所创建的线程。"},{"id":"java13215-pl-P4085949","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"与传统的进程相比，多线程（）。","opts":["A. 编程简单，效率低","B. 编程复杂，效率高","C. 编程简单，效率高","D. 编程复杂，效率低"],"ans":2,"explain":"与传统的进程相比，多线程编程简单，效率高。"},{"id":"java13215-pl-P4085950","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，哪个方法定义了线程要执行的任务或功能？（）","opts":["A. start()","B. run()","C. wait()","D. notify()"],"ans":1,"explain":"Thread类本身只是线程的虚拟CPU，线程所执行的代码或者说线程所要完成的功能，是通过run（）方法来完成的，run（）方法称为线程体，包含在一个特定的对象中。"},{"id":"java13215-pl-P4085951","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在一个单CPU的计算机系统中，以下哪个描述是准确的？（）","opts":["A. 同时有多个线程处于运行状态。","B. 同时只有一个线程处于就绪状态，但可以有多个线程处于运行状态。","C. 任何时候都没有线程处于运行状态。","D. 同时有多个线程处于就绪状态，但只有一个线程处于运行状态。"],"ans":3,"explain":"一般，单CPU情况下，最多只有一个线程处于运行状态，可能会有多个线程处于就绪状态。"},{"id":"java13215-pl-P4085952","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"调用线程的start方法可使线程处于（）。","opts":["A. 新建状态","B. 可运行状态","C. 阻塞状态","D. 死亡状态"],"ans":1,"explain":"调用线程的start（）方法可使线程处于“可运行”状态。"},{"id":"java13215-pl-P4085953","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，以下哪个方法是用于引起线程阻塞的？（）","opts":["A. run()","B. start()","C. sleep()","D. notify()"],"ans":2,"explain":"引起阻塞的原因很多，不同的原因要用不同的方法解除，如sleep（）和wait（）是两个常用的引起阻塞的方法。"},{"id":"java13215-pl-P4085954","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，关于interrupt()方法的作用，以下哪个描述是正确的？（）","opts":["A. interrupt()方法仅用于终止正在运行的线程。","B. interrupt()方法可以中断正在运行的线程，但无法中断处于blocked状态的线程。","C. 当interrupt()方法用于中断处于blocked状态的线程时，该线程会抛出InterruptedException异常。","D. interrupt()方法不会中断任何线程，它仅仅是一个标记，由线程自行检查并响应。"],"ans":2,"explain":"在程序中常常调用interrupt（）来终止线程。interrupt（）不仅可以中断正在运行的线程，而且也能中断处于blocked状态的线程，此时interrupt（）会抛出一个InterruptedException异常。"},{"id":"java13215-pl-P4085955","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，要使一个已经创建的线程真正开始执行，应该调用哪个方法？（）","opts":["A. start()","B. sleep()","C. wait()","D. notify()"],"ans":0,"explain":"虽然一个线程已经被创建，但它实际上并没有立刻运行。要使线程真正在Java环境中运行，必须通过start（）方法来启动，start（）方法也在Thread类中。"},{"id":"java13215-pl-P4085956","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，线程是（）。","opts":["A. 分时的","B. 抢占式的","C. 非抢占式的","D. 非分时的"],"ans":1,"explain":"在Java中，线程调度通常是抢占式，而不是时间片式。"},{"id":"java13215-pl-P4085957","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"同优先级的线程按“（）”的调度原则。","opts":["A. 先进先出","B. 短作业优先","C. 后进先出","D. 轮转法"],"ans":0,"explain":"同优先级的线程按“先进先出”的调度原则。"},{"id":"java13215-pl-P4085958","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，要获取当前正在运行的线程对象，应该使用Thread类中的哪个方法？（）","opts":["A. run()","B. sleep()","C. currentThread()","D. wait()"],"ans":2,"explain":"在程序代码中，可以利用Thread类中的静态方法currentThread（）来引用正在运行的线程。"},{"id":"java13215-pl-P4085959","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"栈具有（）模式。","opts":["A. 先进先出","B. 先进后出","C. 后进先出","D. 后进后出"],"ans":2,"explain":"栈具有“后进先出”模式。"},{"id":"java13215-pl-P4085960","type":"sc","tier":"基础","conf":"adapt","chap":"第10章","q":"在Java中，（）类或接口定义了线程通信的wait、notify和notifyAll方法。","opts":["A. Thread","B. Runnable","C. Object","D. ThreadGroup"],"ans":2,"explain":"在Java语言中，可以用wait（）和notify（）/notifyAll（）方法来协调线程间的运行速度关系，这些方法都定义在java.lang.Object类中。"},{"id":"java13215-pl-P4086132","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：用户在程序界面所进行的操作称为用户事件，对事件的响应称为（）。","opts":[],"ans":null,"explain":"用户在程序界面所进行的操作称为用户事件，对事件的响应称为事件处理。\n事件处理"},{"id":"java13215-pl-P4086133","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：MouseMotionListener接口中声明了两个抽象方法，分别用于处理鼠标的拖动和（）。","opts":[],"ans":null,"explain":"MouseMotionListener接口中声明了两个抽象方法，分别用于处理鼠标的拖动和移动。\n移动"},{"id":"java13215-pl-P4086134","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"填空题：可以使用java.awt包中的（）类来定义和管理颜色。","opts":[],"ans":null,"explain":"可以使用java.awt包中的Color类来定义和管理颜色，Color类的每个对象表示一种颜色。\nColor"},{"id":"java13215-pl-P4086135","type":"sa","tier":"创新","conf":"adapt","chap":"第8章","q":"请写出创建Font类型对象fn的代码，fn的属性值是Courier字体，BOLD样式，20磅字号。","opts":[],"ans":null,"explain":"Font　fn　=　new　Font　(&quot;Courier&quot;,Font.BOLD,20);"},{"id":"java13215-pl-P4086136","type":"sa","tier":"创新","conf":"adapt","chap":"第9章","q":"填空题：菜单栏只有一种构造方法，即（）。","opts":[],"ans":null,"explain":"菜单栏只有一种构造方法，即JMenuBar（）。\nJMenuBar（）"},{"id":"java13215-pl-P4086137","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：（）是进程执行过程中产生的多条执行线索，是比进程单位更小的执行单位，在形式上同进程十分相似——都是用一个按序执行的语句序列来完成特定的功能。","opts":[],"ans":null,"explain":"线程是进程执行过程中产生的多条执行线索，是比进程单位更小的执行单位，在形式上同进程十分相似——都是用一个按序执行的语句序列来完成特定的功能。\n线程"},{"id":"java13215-pl-P4086138","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"简述线程的结构。","opts":[],"ans":null,"explain":"在Java中，线程由3部分组成。<br/>（1）虚拟CPU，封装在java.lang.Thread类中，它控制着整个线程的运行。<br/>（2）执行的代码，传递给Thread类，由Thread类控制按序执行。<br/>（3）处理的数据，传递给Thread类，是在代码执行过程中所要处理的数据。"},{"id":"java13215-pl-P4086139","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：当一个线程被构造时，它由（）、执行代码、操作数据来初始化，这三方面是各自独立的。","opts":[],"ans":null,"explain":"当一个线程被构造时，它由构造方法参数、执行代码、操作数据来初始化，这三方面是各自独立的。\n构造方法参数"},{"id":"java13215-pl-P4086140","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：简述线程的状态。","opts":[],"ans":null,"explain":"线程一共有4种状态，分别是新建（new）、可运行状态（runnable）、死亡（dead）及阻塞（blocked）。\n线程一共有4种状态，分别是新建（new）、可运行状态（runnable）、死亡（dead）及阻塞（blocked）。"},{"id":"java13215-pl-P4086141","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：可以运行但没在运行的线程都排在一个队列中，这个队列称为（）。","opts":[],"ans":null,"explain":"可以运行但没在运行的线程都排在一个队列中，这个队列称为就绪队列。\n就绪队列"},{"id":"java13215-pl-P4086142","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：可运行状态中，正在运行的线程处于运行状态，等待运行的线程处于（）状态。","opts":[],"ans":null,"explain":"可运行状态中，正在运行的线程处于运行状态，等待运行的线程处于就绪状态。\n就绪"},{"id":"java13215-pl-P4086143","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"简述线程死亡的原因。","opts":[],"ans":null,"explain":"线程死亡的原因有两个：一是run（）方法中最后一个语句执行完毕，二是当线程遇到异常退出时便进入了死亡状态。"},{"id":"java13215-pl-P4086144","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：创建线程有两种方法，一种是定义一个继承Thread类的子类，另一种是实现（）接口。","opts":[],"ans":null,"explain":"创建线程有两种方法，一种是定义一个继承Thread类的子类，另一种是实现Runnable接口。\nRunnable"},{"id":"java13215-pl-P4086145","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：在Runnable接口中只定义了一个方法，即void run（），该方法作为（）。","opts":[],"ans":null,"explain":"在Runnable接口中只定义了一个方法，即void run（），该方法作为线程体。\n线程体"},{"id":"java13215-pl-P4086146","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"程序填空题：以下定义的面板子类TimePanel有一个文本域，程序每隔1秒在文本域中更新显示当前时间。 class TimePanel extends JPanel implements Runnable{ Thread TimeThread null; JTextField t; TimePanel(){ t=new JTextField(20); add(t); TimeThread = new ① ; TimeThread.start(); } public void run(){ Date timeNow; while(true){ timeNow= ② ; t.setText(&quot;现在时间：&quot;+timeNow.toString(); try{ sleep(1000); }catch(InterruptedException e){ } } } }","opts":[],"ans":null,"explain":"①Thread(this)<br/>②new　Date()"},{"id":"java13215-pl-P4086147","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"程序填空题：以下程序定义了一个线程类，其功能为显示当前线程的名称。 class MyThrd implements Runnable{ private int i; public void ① { for(i=0;i&lt;5;i++) System.out.println(Thread.currentThread(). ② ); } }","opts":[],"ans":null,"explain":"①run（）<br/>②getName（）"},{"id":"java13215-pl-P4086148","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：用Runnable（）接口实现多线程时，也必须实现run（）方法，需要使用（）方法启动线程，但此时常用Thread类的构造方法来创建线程对象。","opts":[],"ans":null,"explain":"用Runnable（）接口实现多线程时，也必须实现run（）方法，需要使用start（）启动线程，但此时常用Thread类的构造方法来创建线程对象。\nstart（）"},{"id":"java13215-pl-P4086149","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"简述每个线程都有一个优先级，Java的线程调度采用怎样的优先级策略。","opts":[],"ans":null,"explain":"每个线程都有一个优先级，Java的线程调度采用如下的优先级策略。<br/>（1）优先级高的先执行，优先级低的后执行。<br/>（2）每个线程创建时都会被自动分配一个优先级，默认时，继承其父类的优先级。<br/>（3）任务紧急的线程，其优先级较高。<br/>（4）同优先级的线程按“先进先出”的调度原则。"},{"id":"java13215-pl-P4086150","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：sleep（）调用允许低优先级线程运行，而（）方法只给同优先级线程运行的机会。","opts":[],"ans":null,"explain":"sleep（）调用允许低优先级线程运行，而yield（）方法只给同优先级线程运行的机会。\nyield（）"},{"id":"java13215-pl-P4086151","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：暂停一个线程也称为（）。","opts":[],"ans":null,"explain":"有几种方法可以用来暂停一个线程的运行，暂停一个线程也称为挂起。\n挂起"},{"id":"java13215-pl-P4086152","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"简述挂起线程的方法。","opts":[],"ans":null,"explain":"挂起线程的方法有：<br/>（1）sleep（）方法<br/>（2）wait（）和notify（）/notifyAll（）方法<br/>（3）join（）方法"},{"id":"java13215-pl-P4086153","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：在Java语言中，引入了“对象互斥锁”的概念，也称为（），使用它来实现不同线程对共享数据操作的同步。","opts":[],"ans":null,"explain":"在Java语言中，引入了“对象互斥锁”的概念，也称为监视器，使用它来实现不同线程对共享数据操作的同步。\n监视器"},{"id":"java13215-pl-P4086154","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"简述实现“对象互斥锁”的两种方法。","opts":[],"ans":null,"explain":"实现“对象互斥锁”的两种方法：<br/>（1）用关键字synchronized来声明一个方法或一段代码块，该方法或代码块在执行时会获取对象实例的内置锁，其他线程必须等待锁的释放才能访问该方法或代码块中的共享数据。<br/>（2）使用关键字volatile来声明一个共享数据（变量）。但是，使用volatile关键字只能保证数据的可见性和有序性，无法实现对共享数据的原子操作，因此不能完全替代使用synchronized实现同步。"},{"id":"java13215-pl-P4086155","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：在同一时刻只能有一个任务访问的代码区称为（）。","opts":[],"ans":null,"explain":"在同一时刻只能有一个任务访问的代码区称为临界区。\n临界区"},{"id":"java13215-pl-P4086156","type":"sa","tier":"创新","conf":"adapt","chap":"第10章","q":"填空题：java.lang.Object类中定义了三个方法，即（）、notify（）和notifyAll（）。","opts":[],"ans":null,"explain":"java.lang.Object类中定义了三个方法，即wait（）、notify（）和notifyAll（）。\nwait（）"}];
